Object.assign(window.TEM8_DICTIONARY, {"joyous":{"media":{"uk":"media/uk/joyous__gb_1.mp3","us":"media/us/joyous__us_1.mp3"},"oxford":{"phon":"ˈdʒɔɪəs","pos":"adjective","senses":[{"en":"very happy; causing people to be happy","cn":"高兴的；快乐的；令人愉快的","ex":{"en":"joyous laughter","cn":"快乐的笑声"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快乐的；欣喜若狂的","en":"Joyous means extremely happy.","ex":{"en":"She had made their childhood so joyous and carefree.","cn":"她使他们的童年充满欢乐，无忧无虑。"}}]},"examples":[{"en":"joyous laughter","cn":"快乐的笑声"},{"en":"Our music is a joyous celebration of life.","cn":"我们的音乐是对生活的欢乐颂扬。"}]},"jeans":{"media":{"img":["media/pic/shirt_hoodyclothes_comp.jpg","media/thumb/shirt.jpg"],"uk":"media/uk/jeans__gb_1.mp3","us":"media/us/jeans__us_1.mp3"},"oxford":{"phon":"dʒiːnz","pos":"noun","senses":[{"en":"trousers made of denim (= a type of strong cotton)","cn":"牛仔裤；粗斜纹棉布裤","ex":{"en":"I always wear jeans.","cn":"我总是穿牛仔裤。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"牛仔裤；粗斜纹棉布裤","en":"Jeans are casual trousers that are usually made of strong blue cotton cloth called denim."}]},"examples":[{"en":"a faded pair of blue jeans","cn":"一条褪了色的蓝色牛仔裤"}]},"jasmine":{"oxford":{"phon":"ˈdʒæzmɪn","pos":"noun","senses":[{"en":"a plant with white or yellow flowers with a sweet smell, sometimes used to make perfume and also sometimes added to tea","cn":"茉莉；素馨"},{"en":"a first name for girls","cn":"贾斯敏（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"茉莉；素馨","en":"Jasmine is a climbing plant which has small white or yellow flowers with a pleasant smell."}]},"media":{"uk":"media/uk/jasmine__gb_1.mp3","us":"media/us/jasmine__us_1.mp3"}},"jewellery":{"oxford":{"phon":"ˈdʒuːəlri","pos":"noun","senses":[{"en":"objects such as rings and necklaces that people wear as decoration","cn":"珠宝；首饰","lab":"British English","ex":{"en":"silver/gold jewellery","cn":"银首饰；金首饰"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"珠宝；首饰","en":"Jewellery is ornaments that people wear, for example rings, bracelets, and necklaces. It is often made of a valuable metal such as gold, and sometimes decorated with precious stones."}]},"media":{"img":["media/pic/jewellery_comp.jpg","media/thumb/pendant.jpg"],"uk":"media/uk/jewellery__gb_1.mp3","us":"media/us/jewellery__us_1.mp3"},"examples":[{"en":"She has some lovely pieces of jewellery.","cn":"她有几件漂亮的首饰。"},{"en":"silver/gold jewellery","cn":"银/金首饰"}]},"jewish":{"media":{"uk":"media/uk/jewish__gb_1.mp3","us":"media/us/jewish__us_1.mp3"},"oxford":{"phon":"ˈdʒuːɪʃ","pos":"adjective","senses":[{"en":"connected with Judaism; believing in and practising Judaism","cn":"犹太人的；有关犹太人的；犹太教的；信犹太教的","ex":{"en":"We're Jewish.","cn":"我们是犹太人。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"犹太教的；犹太人的","en":"Jewish means belonging or relating to the religion of Judaism or to Jews.","ex":{"en":"...the Jewish festival of the Passover.","cn":"犹太教节日逾越节"}}]},"examples":[{"en":"We're Jewish.","cn":"我们是犹太人。"},{"en":"the local Jewish community","cn":"当地的犹太人群体"}]},"justice":{"media":{"uk":"media/uk/justice__gb_1.mp3","us":"media/us/justice__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪs","pos":"noun","senses":[{"en":"the fair treatment of people","cn":"公平；公正","g":"[uncountable]","ex":{"en":"She spent her life fighting for social justice and equality for women.","cn":"她一生都在为社会正义和妇女平等而奋斗。"}},{"en":"the quality of being fair or reasonable","cn":"公道；合理；公平合理","g":"[uncountable]","ex":{"en":"Who can deny the justice of their cause?","cn":"谁能否认他们的追求是合理的呢？"}},{"en":"the legal system used to punish people who have committed crimes","cn":"司法制度；法律制裁；审判","g":"[uncountable]","lab":"British English","ex":{"en":"the criminal justice system","cn":"刑事司法系统"}},{"en":"a judge in a court (also used before the name of a judge)","cn":"法官（亦作称谓）","g":"[countable]","lab":"North American English"},{"en":"used before the name of a judge in a court of appeal","cn":"（称谓）上诉法院法官","g":"[countable]","lab":"British English, Canadian English，，","ex":{"en":"Mr Justice Davies","cn":"上诉法院法官戴维斯先生"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"公平；公正；正义","en":"Justice is fairness in the way that people are treated.","ex":{"en":"He has a good overall sense of justice and fairness","cn":"他极富正义感和公平意识。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（理由、要求或论点的）合理，正当，正确，公道","en":"The justice of a cause, claim, or argument is its quality of being reasonable, fair, or right.","ex":{"en":"We are a minority and must win people round to the justice of our cause.","cn":"我们属于少数群体，必须赢得人们对我们的正义事业的支持。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"司法制度；法律制度","en":"Justice is the legal system that a country uses in order to deal with people who break the law.","ex":{"en":"Many in Toronto's black community feel that the justice system does not treat them fairly","cn":"多伦多的黑人群体中有很多人觉得司法制度对待他们有失公正。"}},{"pos":"N-COUNT 可数名词","cn":"法官","en":"A justice is a judge.","ex":{"en":"Thomas will be sworn in today as a justice on the Supreme Court.","cn":"托马斯今天将宣誓就任最高法院法官。"}},{"pos":"N-TITLE 头衔名词","cn":"（用于法官名前）…法官","en":"Justice is used before the names of judges.","ex":{"en":"A preliminary hearing was due to start today before Mr Justice Hutchison, but was adjourned.","cn":"今天法官哈奇森先生本来要主持一项预审，但暂时休庭了。"}},{"pos":"PHRASE 短语","cn":"将…绳之以法；把…缉拿归案","en":"If a criminal is brought to justice, he or she is punished for a crime by being arrested and tried in a court of law.","ex":{"en":"They demanded that those responsible be brought to justice","cn":"他们要求将责任人缉拿归案。"}},{"pos":"PHRASE 短语","cn":"准确地再现；逼真地重现","en":"To do justice to a person or thing means to reproduce them accurately and show how good they are.","ex":{"en":"The photograph I had seen didn't do her justice","cn":"我看到的那张照片把她拍得走样了。"}},{"pos":"PHRASE 短语","cn":"妥善应付；恰当处理；尽力全面做好","en":"If you do justice to someone or something, you deal with them properly and completely.","ex":{"en":"No one article can ever do justice to the topic of fraud","cn":"没有哪一篇文章能把欺诈这一话题讲得恰到好处。"}},{"pos":"PHRASE 短语","cn":"充分发挥能力；尽最大的努力","en":"If you do yourself justice, you do something as well as you are capable of doing it.","ex":{"en":"I don't think he could do himself justice playing for England","cn":"我认为他为英格兰队效力时不可能充分发挥自己的水平。"}},{"pos":"PHRASE 短语","cn":"不合法的待遇（或惩罚）","en":"If you describe someone's treatment or punishment as rough justice, you mean that it is not given according to the law.","ex":{"en":"Trial by television makes for very rough justice indeed.","cn":"电视庭审实际上会令审判不公。"}},{"pos":"PHRASE 短语","cn":"不公正的待遇（或惩罚）","en":"If you say that something is rough justice for someone, you mean that they have not been treated fairly.","ex":{"en":"It would have been rough justice had he been deprived of this important third European win.","cn":"要是他被剥夺了这一意义重大的第三个欧洲冠军头衔，那对他简直是太不公平了。"}}]},"examples":[{"en":"You cannot do justice to such a complex situation in just a few pages.","cn":"你不可能仅仅几页就将这么复杂的形势恰如其分地描述出来。"},{"en":"She didn't do herself justice in the exam.","cn":"她在考试中没有充分发挥出自己的水平。"}]},"jam":{"oxford":{"phon":"dʒæm","pos":"noun","senses":[{"en":"a thick sweet substance made by boiling fruit with sugar, often sold in jars and spread on bread","cn":"果酱","g":"[uncountable, countable]","lab":"British English","sc":"sweet food","ex":{"en":"strawberry jam","cn":"草莓酱"}},{"en":"a situation in which it is difficult or impossible to move because there are so many people or vehicles in one particular place","cn":"拥挤；堵塞","g":"[countable]","sc":"many people/vehicles","ex":{"en":"The bus was delayed in a five-mile jam.","cn":"公共汽车因长达五英里的交通堵塞而延误。"}},{"en":"a situation in which a machine does not work because something is stuck in one position","cn":"卡住（因而发生故障）","g":"[countable]","sc":"machine","ex":{"en":"There's a paper jam in the photocopier.","cn":"复印机卡纸了。"}},{"en":"used by the media to describe people who do not have much money to live on (the abbreviation for just about managing)","cn":"卡纸：被媒体用来形容没有多少钱可以赖以生存的人（仅用于管理的缩写）","sc":"people","ex":{"en":"JAMs may be in work, but are struggling to pay for essentials such as food, heating or rent.","cn":"JAM 可能有工作，但难以支付食物、取暖或租金等必需品。"}},{"en":"to push something somewhere with a lot of force","cn":"使劲（往某处）挤（或压、塞）","g":"[transitive]","sc":"push with force","ex":{"en":"He jammed his fingers in his ears.","cn":"他用手指使劲堵住耳朵。"},"pos":"verb"},{"en":"to become unable to move or work; to make something do this","cn":"（使）卡住，不能动弹，不能运转","g":"[intransitive, transitive]","sc":"stop moving/working","ex":{"en":"The photocopier keeps jamming up.","cn":"这台复印机总是卡纸。"},"pos":"verb"},{"en":"to put somebody/something into a small space where there is very little room to move","cn":"塞入；塞进；挤进","g":"[transitive, usually passive, intransitive]","sc":"put into small space","ex":{"en":"Six of us were jammed into one small car.","cn":"我们六个人被塞进一辆小汽车里。"},"pos":"verb"},{"en":"to fill something with a large number of people or things so that it is unable to function as it should","cn":"挤满；塞紧","g":"[transitive]","sc":"fill with people/things","ex":{"en":"Viewers jammed the switchboard with complaints.","cn":"打电话投诉的观众使总机应接不暇。"},"pos":"verb"},{"en":"to send out radio signals to prevent a radio broadcast from being heard, or to prevent a radio or phone from sending or receiving signals","cn":"（发射无线电波）干扰","g":"[transitive]","lab":"specialist","sc":"radio broadcast","pos":"verb"},{"en":"to play music with other musicians in an informal way without preparing or practising first","cn":"即兴演奏","g":"[intransitive, transitive]","sc":"play music","pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"果酱","en":"Jam is a thick sweet food that is made by cooking fruit with a large amount of sugar, and that is usually spread on bread.","ex":{"en":"...home-made jam.","cn":"自制果酱"}},{"pos":"VERB 动词","cn":"硬推；硬塞；使劲放","en":"If you jam something somewhere, you push or put it there roughly.","ex":{"en":"He picked his cap up off the ground and jammed it on his head","cn":"他从地上捡起帽子，猛地扣到头上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（机器）卡住；使卡住；（使）不能运转","en":"If something such as a part of a machine jams, or if something jams it, the part becomes fixed in position and is unable to move freely or work properly.","ex":{"en":"The second time he fired his gun jammed","cn":"他开第二枪时枪卡壳了。"}},{"pos":"VERB 动词","cn":"（车辆）堵住，堵塞（道路）","en":"If vehicles jam a road, there are so many of them that they cannot move.","ex":{"en":"Hundreds of departing motorists jammed the roads.","cn":"数百名打算驾车离开的司机堵住了道路。"}},{"pos":"VERB 动词","cn":"（人）塞进，挤进","en":"If a lot of people jam a place, or jam into a place, they are pressed tightly together so that they can hardly move.","ex":{"en":"Hundreds of people jammed the boardwalk to watch","cn":"数百人挤在木板人行道上观看。"}},{"pos":"VERB 动词","cn":"干扰（无线电或电子信号）","en":"To jam a radio or electronic signal means to interfere with it and prevent it from being received or heard clearly.","ex":{"en":"They will try to jam the transmissions electronically.","cn":"他们会试图用电子信号对发射进行干扰。"}},{"pos":"VERB 动词","cn":"使（电话总机）应接不暇；使（电话线）过于繁忙","en":"If callers are jamming telephone lines, there are so many callers that the people answering the telephones find it difficult to deal with them all.","ex":{"en":"Hundreds of callers jammed the BBC switchboard for more than an hour","cn":"在一个多小时内，成百上千的来电使得英国广播公司的总机应接不暇。"}},{"pos":"N-SING 单数名词","cn":"陷入困境","en":"If someone is in a jam, they are in a very difficult situation.","ex":{"en":"They were in a real jam, Bob thought glumly.","cn":"他们确实遇上麻烦了，鲍勃闷闷不乐地想。"}},{"pos":"VERB 动词","cn":"（爵士乐手或摇滚乐手）即兴演奏","en":"When jazz or rock musicians are jamming, they are informally playing music that has not been written down or planned in advance.","ex":{"en":"He was jamming with his saxophone.","cn":"他在即兴吹奏萨克斯管。"}}]},"media":{"uk":"media/uk/jam__gb_1.mp3","us":"media/us/jam__us_1.mp3","img":["media/ldoce/img/croissant.jpg"]},"examples":[{"en":"The bus was delayed in a five-mile jam.","cn":"公共汽车因长达五英里的交通堵塞而延误。"},{"en":"As fans rushed to leave, jams formed at all the exits.","cn":"因球迷都急于离开，所有出口都给阻塞了。"}]},"january":{"media":{"uk":"media/uk/january__gb_1.mp3","us":"media/us/january__us_1.mp3"},"oxford":{"phon":"ˈdʒænjuəri","pos":"noun","senses":[{"en":"the 1st month of the year, between December and February","cn":"一月","lab":"British English","ex":{"en":"She was born in January.","cn":"她出生在一月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"一月","en":"January is the first month of the year in the Western calendar.","ex":{"en":"We always have snow in January","cn":"我们这儿1月份总会下雪。"}}]}},"juice":{"media":{"uk":"media/uk/juice__gb_1.mp3","us":"media/us/juice__us_1.mp3","img":["media/ldoce/img/orange_juice.jpg"]},"oxford":{"phon":"dʒuːs","pos":"noun","senses":[{"en":"the liquid that comes from fruit or vegetables; a drink made from this","cn":"果汁；菜汁；果汁（或菜汁）饮料","g":"[uncountable, countable]","ex":{"en":"a glass of fruit juice","cn":"一杯果汁"}},{"en":"the liquid that comes out of a piece of meat when it is cooked","cn":"肉汁","g":"[countable, usually plural, uncountable]","ex":{"en":"Use the juices of the meat to make gravy.","cn":"用肉汁来做卤汁。"}},{"en":"the liquid in the stomach that helps you to digest food","cn":"胃液；消化液","g":"[countable, usually plural]","ex":{"en":"digestive/gastric juices","cn":"消化液；胃液"}},{"en":"electricity","cn":"电","g":"[uncountable]","lab":"informal","ex":{"en":"My phone has run out of juice.","cn":"我的手机没电了。"}},{"en":"petrol","cn":"汽油","g":"[uncountable]","lab":"especially British English, informal，，"},{"en":"a liquid containing nicotine that is used in a device for vaping","cn":"烟油","g":"[uncountable]","lab":"informal"},{"en":"to get the juice out of fruit or vegetables","cn":"榨出（水果或蔬菜的）汁液；将…榨汁","ex":{"en":"Juice two oranges.","cn":"将两个橙子榨汁。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"果汁","en":"Juice is the liquid that can be obtained from a fruit.","ex":{"en":"...fresh orange juice","cn":"鲜榨橙汁"}},{"pos":"N-PLURAL 复数名词","cn":"肉汁","en":"The juices of a piece of meat are the liquid that comes out of it when you cook it.","ex":{"en":"When cooked, drain off the juices and put the meat in a processor or mincer.","cn":"肉煮熟后，沥干肉汁，将其放入食品加工机或绞肉机中。"}},{"pos":"N-PLURAL 复数名词","cn":"胃液;消化液","en":"The juices in your stomach are the fluids that help you to digest food."}]},"examples":[{"en":"Add the juice of two lemons.","cn":"加两个柠檬的汁。"},{"en":"Juice two oranges.","cn":"将两个橙子榨汁。"}]},"jack":{"media":{"uk":"media/uk/jack__gb_1.mp3","us":"media/us/jack__us_1.mp3"},"oxford":{"phon":"dʒæk","pos":"noun","senses":[{"en":"a device for raising heavy objects off the ground, especially vehicles so that a wheel can be changed","cn":"千斤顶，起重器（换车轮时常用）","g":"[countable]"},{"en":"an electronic connection between two pieces of electrical equipment","cn":"（电）插孔，插座，插口；塞孔","g":"[countable]"},{"en":"a card with a picture of a young man on it, normally worth more than a ten and less than a queen","cn":"J 牌；杰克","g":"[countable]","ex":{"en":"the jack of clubs","cn":"梅花 J"}},{"en":"a small white ball towards which players roll larger balls","cn":"靶子球（白色，较其他球小）","g":"[countable]"},{"en":"a children’s game in which players bounce a small ball and pick up small metal objects, also called jacks, before catching the ball","cn":"抛接子游戏（儿童游戏）","g":"[plural]"},{"en":"anything or nothing at all","cn":"丝毫，根本，一点儿（不）","g":"[uncountable]","lab":"taboo","ex":{"en":"You don't know jack.","cn":"你什么都不知道。"}},{"en":"to steal something from somebody, especially something small or of low value","cn":"偷，悄悄拿走，窃取（尤指小的或不值钱的东西）","ex":{"en":"Someone jacked my seat.","cn":"有人偷偷占了我的座位。"},"pos":"verb"},{"en":"tired of or bored with somebody/something","cn":"（对…）厌倦，厌烦","pos":"adjective"},{"en":"a first name for boys, sometimes short for John","cn":"杰克（男子名，有时为 John 缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"千斤顶；起重器","en":"A jack is a device for lifting a heavy object off the ground, for example a car."},{"pos":"N-COUNT 可数名词","cn":"（纸牌中的）J牌，杰克","en":"A jack is a playing card whose value is between a ten and a queen. A jack is usually represented by a picture of a young man."},{"pos":"","cn":"","en":"相关词组：jack in jack up"}]},"examples":[{"en":"Let's go. We're being jacked around here.","cn":"咱们走吧。别在这儿浪费时间了。"},{"en":"Drug users were jacking up in the stairwells.","cn":"当时瘾君子正在楼梯井注射毒品。"}]},"journalist":{"oxford":{"phon":"ˈdʒɜːnəlɪst","pos":"noun","senses":[{"en":"a person whose job is to collect and write news stories for newspapers, magazines, radio, television or online news sites","cn":"新闻记者；新闻工作者","ex":{"en":"a freelance journalist","cn":"自由记者"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新闻记者；新闻工作者","en":"A journalist is a person whose job is to collect news and write about it for newspapers, magazines, television, or radio."}]},"media":{"uk":"media/uk/journalist__gb_1.mp3","us":"media/us/journalist__us_1.mp3"},"examples":[{"en":"a well-known journalist and broadcaster","cn":"一位著名的新闻记者兼播音员"}]},"joy":{"media":{"uk":"media/uk/joy__gb_1.mp3","us":"media/us/joy__us_1.mp3"},"oxford":{"phon":"dʒɔɪ","pos":"noun","senses":[{"en":"a feeling of great happiness","cn":"高兴；愉快；喜悦","g":"[uncountable]","ex":{"en":"Her books have brought joy to millions.","cn":"她的书给数百万人带来了欢乐。"}},{"en":"a person or thing that causes you to feel very happy","cn":"令人高兴的人（或事）；乐事；乐趣","g":"[countable]","ex":{"en":"the joys of fatherhood","cn":"做父亲的乐趣"}},{"en":"success or satisfaction","cn":"成功；满意；满足","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"We complained about our rooms but got no joy from the manager.","cn":"我们抱怨房间不好，经理却不理会。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"欢欣；愉快；喜悦","en":"Joy is a feeling of great happiness.","ex":{"en":"Salter shouted with joy.","cn":"索尔特欣喜地叫喊着。"}},{"pos":"N-COUNT 可数名词","cn":"令人高兴的事（或人）；乐事；乐趣","en":"A joy is something or someone that makes you feel happy or gives you great pleasure.","ex":{"en":"One can never learn all there is to know about cooking, and that is one of the joys of being a chef","cn":"钻研烹饪之道是永无止境的，这也是当厨师的乐趣之一。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"成功；好运","en":"If you get no joy, you do not have success or luck in achieving what you are trying to do.","ex":{"en":"They expect no joy from the vote itself","cn":"他们对投票本身不抱任何希望。"}},{"pos":"PHRASE 短语","cn":"欢欣鼓舞；欣喜若狂","en":"If you say that someone is jumping for joy, you mean that they are very pleased or happy about something.","ex":{"en":"He jumped for joy on being told the news.","cn":"得知这个消息，他高兴得手舞足蹈。"}},{"pos":"","cn":"","en":"one's pride and joy→see: ;"}]},"examples":[{"en":"‘Any joy at the shops?’ ‘No, they didn't have what I wanted.’ “","cn":"逛商店有收获吗？” “没有，哪里都没有我想要的。”"},{"en":"I didn't expect them to jump for joy at the news (= to be very pleased).","cn":"没想到他们听到这消息高兴得跳了起来。"}]},"jury":{"oxford":{"phon":"ˈdʒʊəri","pos":"noun","senses":[{"en":"a group of members of the public who listen to the facts of a case in a court and decide whether or not somebody is guilty of a crime, or whether a claim has been proved","cn":"陪审团","lab":"especially in North American English","ex":{"en":"members of the jury","cn":"陪审团成员"}},{"en":"a group of people who decide who is the winner of a competition","cn":"（比赛的）评判委员会，裁判委员会，仲裁委员会","ex":{"en":"He was on the jury for this year's Booker Prize.","cn":"他是今年布克奖的评委。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"陪审团","en":"In a court of law, the jury is the group of people who have been chosen from the general public to listen to the facts about a crime and to decide whether the person accused is guilty or not.","ex":{"en":"The jury convicted Mr Hampson of all offences.","cn":"陪审团裁定汉普森先生全部罪名成立。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（竞赛的）评判委员会，裁判委员会","en":"A jury is a group of people who choose the winner of a competition.","ex":{"en":"I am not surprised that the Booker Prize jury included it on their shortlist.","cn":"我毫不惊讶布克奖评委会将其列在入选名单中。"}},{"pos":"PHRASE 短语","cn":"（某事）悬而未决，仍未达成定论","en":"If you say that the jury is out or that the jury is still out on a particular subject, you mean that people in general have still not made a decision or formed an opinion about that subject.","ex":{"en":"The jury is out on whether or not this is true","cn":"这是否属实仍未得出定论。"}}]},"media":{"uk":"media/uk/jury__gb_1.mp3","us":"media/us/jury__us_1.mp3"},"examples":[{"en":"The jury has/have returned a verdict of guilty.","cn":"陪审团已作出有罪裁定。"},{"en":"the right to trial by jury","cn":"经由陪审团审判的权利"}]},"joins":{"oxford":{"phon":"dʒɔɪn","pos":"verb","senses":[{"en":"to fix or connect two or more things together","cn":"连接；接合；联结"},{"en":"if two things or groups join , or if one thing or group joins another, they come together to form one thing or group","cn":"结合；联合；汇合"}]},"media":{"uk":"media/uk/join__gb_1.mp3","us":"media/us/join__us_1.mp3"}},"judgment":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力"},{"en":"an opinion that you form about sth after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"看法；意见；评价","en":"A judgment is an opinion that you have or express after thinking carefully about something.","ex":{"en":"In your judgment, what has changed over the past few years?","cn":"依你看，过去几年里发生了什么改变呢？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"判断力；识别力","en":"Judgment is the ability to make sensible guesses about a situation or sensible decisions about what to do.","ex":{"en":"I respect his judgement and I'll follow any advice he gives me","cn":"我尊重他的判断能力，会接受他提出的任何建议。"}},{"pos":"N-VAR 可变名词","cn":"判决；裁决","en":"A judgment is a decision made by a judge or by a court of law.","ex":{"en":"The industry was awaiting a judgment from the European Court","cn":"该行业正在等待欧洲法庭作出裁决。"}},{"pos":"PHRASE 短语","cn":"明知不适当地；违心地","en":"If something is against your better judgment, you believe that it would be more sensible or better not to do it.","ex":{"en":"Against my better judgement I agreed","cn":"我勉强同意了。"}},{"pos":"PHRASE 短语","cn":"作出评价；（尤指）批评，指责","en":"If you pass judgment on someone or something, you give your opinion about it, especially if you are making a criticism.","ex":{"en":"It's not for me to pass judgement, it's a personal matter between the two of you","cn":"不该由我来说三道四，这是你们两个人之间的私事。"}},{"pos":"PHRASE 短语","cn":"保留意见；暂不发表意见","en":"If you reserve judgment on something, you refuse to give an opinion about it until you know more about it.","ex":{"en":"Doctors are reserving judgement on his ability to travel until later in the week.","cn":"医生们要等到这周晚些时候再决定他是否适宜旅行。"}},{"pos":"PHRASE 短语","cn":"审判；判定","en":"To sit in judgment means to decide whether or not someone is guilty of doing something wrong.","ex":{"en":"He argues very strongly that none of us has the right to sit in judgement.","cn":"他激烈地争论说，我们中任何一个人都无权进行审判。"}}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdejudgment.mp3","us":"media/ldoce/hwd/ame/2/laadjudgment.mp3"},"examples":[{"en":"It’s too soon to make a judgment about what the outcome will be.","cn":"现在就判断结果会怎样还为时过早。"},{"en":"In my judgment, we should accept his offer.","cn":"依我看﹐我们应该接受他的报价。"}]},"judge":{"media":{"uk":"media/uk/judge__gb_1.mp3","us":"media/us/judge__us_1.mp3"},"oxford":{"phon":"dʒʌdʒ","pos":"noun","senses":[{"en":"a person in a court who has the authority to decide how criminals should be punished or to make legal decisions","cn":"法官；审判员","sc":"in court","ex":{"en":"a High Court judge","cn":"高等法院的法官"}},{"en":"a person who decides who has won a competition","cn":"裁判员；评判员","sc":"in competition","ex":{"en":"The judges' decision is final.","cn":"裁判的决定为最终决定。"}},{"en":"a person who has the necessary knowledge or skills to give their opinion about the value or quality of somebody/something","cn":"鉴定人；鉴赏家","g":"[usually singular]","sc":"somebody who gives opinion","ex":{"en":"She's a good judge of character.","cn":"她很善于判断人的性格。"}},{"en":"to form an opinion about somebody/something, based on the information you have","cn":"判断；断定；认为","g":"[intransitive, transitive]","sc":"form opinion","ex":{"en":"As far as I can judge, all of them are to blame.","cn":"依我看，他们都应承担责任。"},"pos":"verb"},{"en":"to guess the size, amount, etc. of something","cn":"估计，猜测（大小、数量等）","g":"[transitive]","sc":"estimate","ex":{"en":"Young children are unable to judge the speed of traffic.","cn":"小孩子无法判断车辆的速度。"},"pos":"verb"},{"en":"to decide the result of a competition; to be the judge in a competition","cn":"裁判；评判；担任裁判","g":"[transitive, intransitive]","sc":"in competition","ex":{"en":"She was asked to judge the essay competition.","cn":"她被邀请担任作文比赛的评委。"},"pos":"verb"},{"en":"to give your opinion about somebody, especially when you think they are bad","cn":"评价；鉴定；（尤指）批评，指责","g":"[transitive, intransitive]","sc":"give opinion","ex":{"en":"What gives you the right to judge other people?","cn":"你有什么权利对别人评头论足？"},"pos":"verb"},{"en":"to decide whether somebody is guilty or innocent in a court","cn":"审判；审理；判决","g":"[transitive]","sc":"in court","ex":{"en":"to judge a case","cn":"审理案件"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"法官；审判官","en":"A judge is the person in a court of law who decides how the law should be applied, for example how criminals should be punished.","ex":{"en":"The judge adjourned the hearing until next Tuesday","cn":"法官将听证会延至下周二。"}},{"pos":"N-COUNT 可数名词","cn":"裁判员；评判员","en":"A judge is a person who decides who will be the winner of a competition.","ex":{"en":"A panel of judges is now selecting the finalists.","cn":"评判小组现在正选拔参加决赛的选手。"}},{"pos":"VERB 动词","cn":"为（竞赛等）担任裁判；评定","en":"If you judge something such as a competition, you decide who or what is the winner.","ex":{"en":"Colin Mitchell will judge the entries each week","cn":"科林·米切尔负责每周对参赛作品进行评判。"}},{"pos":"VERB 动词","cn":"判断；断定；评价；认为","en":"If you judge something or someone, you form an opinion about them after you have examined the evidence or thought carefully about them.","ex":{"en":"It will take a few more years to judge the impact of these ideas","cn":"要再花上几年的时间才能判断出这些想法的影响。"}},{"pos":"VERB 动词","cn":"估计，猜测（数量、大小、价值等）","en":"If you judge something, you guess its amount, size, or value or you guess what it is.","ex":{"en":"It is important to judge the weight of your washing load correctly","cn":"正确估计待洗衣物的重量很重要。"}},{"pos":"N-COUNT 可数名词","cn":"鉴赏家；鉴定人","en":"If someone is a good judge of something, they understand it and can make sensible decisions about it. If someone is a bad judge of something, they cannot do this.","ex":{"en":"I'm a pretty good judge of character","cn":"我很善于判断人的性格。"}},{"pos":"PREP-PHRASE 短语介词","cn":"根据…判断；根据…来看","en":"You use judging by ,judging from, or to judge from to introduce the reasons why you believe or think something.","ex":{"en":"Judging by the opinion polls, he seems to be succeeding","cn":"从民意测验来看，他似乎胜券在握。"}},{"pos":"PHRASE 短语","cn":"根据判断；看来","en":"If you say that something is true as far as you can judge or so far as you can judge, you are assuming that it is true, although you do not know all the facts about it.","ex":{"en":"They were typed records of his bets, going back a couple of years as far as I could judge","cn":"据我判断，这些是他过去几年下注打赌的书面记录。"}}]},"examples":[{"en":"‘I'm not sure that's a good way to do it.’ ‘ Let me be the judge of that. ’ “","cn":"我拿不准这样做好不好。” “就让我来判断吧。”"},{"en":"Each painting must be judged on its own merits.","cn":"任何一幅画都必须根据其本身的价值来评判。"}]},"join":{"media":{"uk":"media/uk/join__gb_1.mp3","us":"media/us/join__us_1.mp3"},"oxford":{"phon":"dʒɔɪn","pos":"verb","senses":[{"en":"to fix or connect two or more things together","cn":"连接；接合；联结","g":"[transitive, intransitive]","sc":"connect","ex":{"en":"Join one section of pipe to the next.","cn":"将一段管子与相邻的管子连接起来。"}},{"en":"if two things or groups join, or if one thing or group joins another, they come together to form one thing or group","cn":"结合；联合；汇合","g":"[intransitive, transitive]","sc":"become one","ex":{"en":"the place where the two paths join","cn":"两条小路汇合的地方"}},{"en":"to become a member of an organization, a company, a club, etc.","cn":"成为…的一员；参加；加入","g":"[transitive, intransitive]","lab":"figurative","sc":"club/company","ex":{"en":"I've joined an aerobics class.","cn":"我参加了有氧健身班。"}},{"en":"to take part in something that somebody else is doing or to go somewhere with them","cn":"参与；加入到…之中；与…一道去","g":"[transitive]","sc":"do something with somebody else","ex":{"en":"Do you mind if I join you?","cn":"我和你们在一起，可以吗？"}},{"en":"if you join a train, plane, etc. you get on it","cn":"上（火车、飞机等）","g":"[transitive]","lab":"British English","sc":"train/plane"},{"en":"if you join a road or a line of people, you start to travel along it, or move into it","cn":"上（路）；加入（行列）","g":"[transitive]","sc":"road/path/line"},{"en":"a place where two things are fixed together","cn":"连接处；接合点","sc":"connection","ex":{"en":"The two pieces were stuck together so well that you could hardly see the join.","cn":"这两块黏合得太好了，几乎看不出接缝。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（人或交通工具）加入…之中，与…一道去，与…会合","en":"If one person or vehicle joins another, they move or go to the same place, for example so that both of them can do something together.","ex":{"en":"His wife and children moved to join him in their new home","cn":"他的妻子和孩子们搬进了他们的新家，和他一起生活。"}},{"pos":"VERB 动词","cn":"加入（组织或机构）；成为…的一员；参加","en":"If you join an organization, you become a member of it or start work as an employee of it.","ex":{"en":"He joined the Army five years ago","cn":"他5年前参军了。"}},{"pos":"VERB 动词","cn":"参与（活动）","en":"If you join an activity that other people are doing, you take part in it or become involved with it.","ex":{"en":"Telephone operators joined the strike and four million engineering workers are also planning action","cn":"电话接线员加入了罢工的行列，400万工程技术工人也在计划采取行动。"}},{"pos":"VERB 动词","cn":"加入（队伍）；排（队）","en":"If you join a queue, you stand at the end of it so that you are part of it.","ex":{"en":"Make sure you join the queue inside the bank.","cn":"在银行里一定要排队。"}},{"pos":"VERB 动词","cn":"连接；接合","en":"To join two things means to fix or fasten them together.","ex":{"en":"The opened link is used to join the two ends of the chain.","cn":"开口的链环是用来将链子的两头连接起来的。"}},{"pos":"VERB 动词","cn":"（线、小路等）连接，贯通","en":"If something such as a line or path joins two things, it connects them.","ex":{"en":"It has a dormer roof joining both gable ends","cn":"带天窗的斜屋顶连接着两边的山墙。"}},{"pos":"V-RECIP 相互动词","cn":"（道路或河流）会合，汇合，交汇","en":"If two roads or rivers join, they meet or come together at a particular point.","ex":{"en":"Do you know the highway to Tulsa? The airport road joins it.","cn":"你知道通向塔尔萨的公路吗？去机场的路和它交会。"}},{"pos":"N-COUNT 可数名词","cn":"连接处；接合点；接头；接缝","en":"A join is a place where two things are fastened or fixed together."},{"pos":"","cn":"","en":"join forces→see: ; to join the ranks→see: ;"},{"pos":"","cn":"","en":"相关词组：join in join up"}]},"examples":[{"en":"( figurative ) Local residents have joined battle with the council over the lack of parking facilities.","cn":"当地居民就缺少停车设施一事与政务委员会展开了斗争。"},{"en":"I'm sure you'll all join me in wishing Ted and Laura a very happy marriage.","cn":"我相信大家会愿意与我一起共祝特德和劳拉喜结良缘。"}]},"joint":{"oxford":{"phon":"dʒɔɪnt","pos":"adjective","senses":[{"en":"involving two or more people together","cn":"联合的；共同的","ex":{"en":"a joint account (= a bank account in the name of more than one person, for example shared by a couple)","cn":"联名账户"}},{"en":"a place where two bones are joined together in the body in a way that enables them to bend and move","cn":"关节","ex":{"en":"inflammation of the knee joint","cn":"膝关节发炎"},"pos":"noun"},{"en":"a place where two or more parts of an object are joined together, especially to form a corner","cn":"（尤指构成拐角的）接头，接合处，接点","ex":{"en":"a joint between two lengths of copper","cn":"两段铜管之间的接缝"},"pos":"noun"},{"en":"a piece of roast meat","cn":"一块烤肉","lab":"British English","ex":{"en":"a joint of beef","cn":"一块烤牛肉"},"pos":"noun"},{"en":"a place where people meet to eat, drink, dance, etc., especially one that is cheap","cn":"公共场所（尤指价格低廉的饮食和娱乐场所）","lab":"informal","ex":{"en":"a fast-food joint","cn":"快餐店"},"pos":"noun"},{"en":"a cigarette containing marijuana (= an illegal drug)","cn":"大麻烟卷","lab":"informal","pos":"noun"},{"en":"to cut meat into large pieces, usually each containing a bone","cn":"把…切成带骨的大块肉","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"联合的；共同的；共享的","en":"Joint means shared by or belonging to two or more people.","ex":{"en":"She and Frank had never gotten around to opening a joint account","cn":"她和弗兰克还没有抽出时间去开联名账户。"}},{"pos":"N-COUNT 可数名词","cn":"关节","en":"A joint is a part of your body such as your elbow or knee where two bones meet and are able to move together.","ex":{"en":"Her joints ache if she exercises.","cn":"她一运动关节就疼。"}},{"pos":"N-COUNT 可数名词","cn":"接合处；连接点；接头；接缝","en":"A joint is the place where two things are fastened or fixed together."},{"pos":"N-COUNT 可数名词","cn":"（适于烧烤的）大块肉","en":"A joint is a fairly large piece of meat which is suitable for roasting.","ex":{"en":"He carved the joint of beef.","cn":"他切开了那一大块烤牛肉。"}},{"pos":"N-COUNT 可数名词","cn":"廉价娱乐场所；下等娱乐场所","en":"You can refer to a cheap place where people go for some form of entertainment as a joint .","ex":{"en":"They had come to the world's most famous pick-up joint","cn":"他们来到了全世界最有名的寻花问柳之地。"}},{"pos":"N-COUNT 可数名词","cn":"大麻烟卷","en":"A joint is a cigarette which contains cannabis or marijuana."},{"pos":"PHRASE 短语","cn":"（因感到无足轻重或不受重视）心烦意乱，感到不快","en":"If something puts someone's nose out of joint, it upsets or offends them because it makes them feel less important or less valued.","ex":{"en":"Barry had his nose put out of joint by Lucy's aloof sophistication","cn":"露西的冷淡与世故使得巴里十分不快。"}},{"pos":"PHRASE 短语","cn":"不太正常；不得体；无秩序；紊乱","en":"If something is out of joint, it is not quite right or appropriate, or does not work quite as it should.","ex":{"en":"There was something out of joint in the situation. Something was strange","cn":"情况有点儿不太正常。有些事有点儿古怪。"}}]},"media":{"uk":"media/uk/joint__gb_1.mp3","us":"media/us/joint__us_1.mp3"},"examples":[{"en":"The report was a joint effort (= we worked on it together).","cn":"这个报告是大家共同努力的成果。"},{"en":"The event was organized jointly by students and staff.","cn":"这项活动是由师生共同组织的。"}]},"judgements":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力"},{"en":"an opinion that you form about sth after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价"}]}},"jealousy":{"media":{"uk":"media/uk/jealousy__gb_1.mp3","us":"media/us/jealousy__us_1.mp3"},"oxford":{"phon":"ˈdʒeləsi","pos":"noun","senses":[{"en":"a feeling of being jealous","cn":"忌妒；妒羡；羡慕","g":"[uncountable]","ex":{"en":"I felt sick with jealousy.","cn":"我羡慕得要死。"}},{"en":"an action or a remark that shows that a person is jealous","cn":"忌妒，妒羡，羡慕（的言行）","g":"[countable]","ex":{"en":"I'm tired of her petty jealousies.","cn":"我厌烦她那小肚鸡肠的忌妒。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"妒忌；吃醋；小心提防","en":"Jealousy is the feeling of anger or bitterness which someone has when they think that another person is trying to take a lover or friend, or a possession, away from them.","ex":{"en":"At first his jealousy only showed in small ways — he didn't mind me talking to other guys.","cn":"起初他的小心眼表现得不是十分明显——他并不介意我和其他男人说话。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"妒羡；羡慕","en":"Jealousy is the feeling of anger or bitterness which someone has when they wish that they could have the qualities or possessions that another person has.","ex":{"en":"Her beauty causes envy and jealousy.","cn":"她的美貌惹来嫉妒和羡慕。"}}]},"examples":[{"en":"I'm tired of her petty jealousies.","cn":"我厌烦她那小肚鸡肠的忌妒。"},{"en":"I felt sick with jealousy.","cn":"我羡慕得要死。"}]},"james":{"oxford":{"phon":"dʒeɪmz","pos":"","senses":[{"en":"a first name for boys","cn":"詹姆斯（男子名）"}]},"media":{"uk":"media/uk/jam__gb_1.mp3","us":"media/us/jam__us_1.mp3"}},"judgement":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力","g":"[uncountable]","ex":{"en":"good/poor/sound judgement","cn":"判断力强／弱；正确的判断力"}},{"en":"an opinion that you form about something after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价","g":"[countable, uncountable]","ex":{"en":"In his portrait of the dictator he avoids any moral judgements.","cn":"在对独裁者的描述中，他避免做任何道德判断。"}},{"en":"the decision of a court or a judge","cn":"判决；裁决","g":"[countable, uncountable]","ex":{"en":"a judgment from the European Court of Justice","cn":"欧洲法院的判决"}},{"en":"something bad that happens to somebody that is thought to be a punishment from God","cn":"报应；天谴；（上帝对人的）审判","g":"[countable, usually singular]","lab":"formal"}]},"media":{"uk":"media/uk/judgement__gb_1.mp3","us":"media/us/judgement__us_1.mp3"},"examples":[{"en":"It's not something I can give you rules for; you'll have to use your judgement.","cn":"不是我把规则告诉你就行了，你得运用自己的判断力。"},{"en":"He achieved his aim more by luck than judgement.","cn":"他达到目的主要是靠运气而不是靠判断力。"}]},"journey":{"media":{"uk":"media/uk/journey__gb_1.mp3","us":"media/us/journey__us_1.mp3"},"oxford":{"phon":"ˈdʒɜːni","pos":"noun","senses":[{"en":"an act of travelling from one place to another, especially when they are far apart","cn":"（尤指长途）旅行，行程","lab":"British English","ex":{"en":"They went on a long train journey across India.","cn":"他们乘火车作了一次横跨印度的长途旅行。"}},{"en":"a long and often difficult process of personal change and development","cn":"心路历程；人生转变","ex":{"en":"I was excited by the character's journey in the film.","cn":"我对电影中角色的旅程感到兴奋。"}},{"en":"to travel, especially a long distance","cn":"（尤指长途）旅行","ex":{"en":"They journeyed for seven long months.","cn":"他们旅行了七个月之久。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行；行程","en":"When you make a journey, you travel from one place to another.","ex":{"en":"There is an express service from Paris which completes the journey to Bordeaux in under 4 hours.","cn":"从巴黎有快车前往波尔多，全程不到4个小时。"}},{"pos":"N-COUNT 可数名词","cn":"（心灵的）历程","en":"You can refer to a person's experience of changing or developing from one state of mind to another as a journey.","ex":{"en":"How do we go about embarking on this 'inner journey' to understand ourselves?","cn":"我们该如何开始这个“心灵历程”来了解自己呢？"}},{"pos":"VERB 动词","cn":"旅行","en":"If you journey somewhere, you travel there.","ex":{"en":"In February 1935, Naomi journeyed to the United States for the first time","cn":"1935年2月，娜奥米第一次来到美国旅行。"}}]},"examples":[{"en":"( figurative ) The book describes a spiritual journey from despair to happiness.","cn":"这本书描述了从绝望到高兴的心理变化过程。"},{"en":"They went on a long train journey across India.","cn":"他们乘火车作了一次横跨印度的长途旅行。"}]},"june":{"media":{"uk":"media/uk/june__gb_1.mp3","us":"media/us/june__us_1.mp3"},"oxford":{"phon":"dʒuːn","pos":"noun","senses":[{"en":"the 6th month of the year, between May and July","cn":"六月","lab":"British English","ex":{"en":"She was born in June.","cn":"她出生在六月。"}},{"en":"a first name for girls","cn":"朱妮（女子名）"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"六月","en":"June is the sixth month of the year in the Western calendar.","ex":{"en":"He spent two and a half weeks with us in June 1986","cn":"1986年6月他和我们一起呆了两周半。"}}]}},"juices":{"oxford":{"phon":"dʒuːs","pos":"noun","senses":[{"en":"the liquid that comes from fruit or vegetables; a drink made from this","cn":"果汁；菜汁；果汁（或菜汁）饮料"},{"en":"the liquid that comes out of a piece of meat when it is cooked","cn":"肉汁"}]},"media":{"uk":"media/uk/juice__gb_1.mp3","us":"media/us/juice__us_1.mp3"}},"judgments":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力"},{"en":"an opinion that you form about sth after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价"}]}},"journalists":{"oxford":{"phon":"ˈdʒɜːnəlɪst","pos":"noun","senses":[{"en":"a person whose job is to collect and write news stories for newspapers, magazines, radio or television","cn":"新闻记者；新闻工作者"}]}},"jerk":{"media":{"uk":"media/uk/jerk__gb_1.mp3","us":"media/us/jerk__us_1.mp3"},"oxford":{"phon":"dʒɜːk","pos":"verb","senses":[{"en":"to move or to make something move with a sudden short sharp movement","cn":"急拉；猛推；猝然一动","ex":{"en":"She jerked her head up.","cn":"她猛然抬起头来。"}},{"en":"a sudden quick sharp movement","cn":"急拉；猛推；猝然一动","g":"[countable]","ex":{"en":"She sat up with a jerk.","cn":"她猛地坐了起来。"},"pos":"noun"},{"en":"an offensive word for somebody who you think is stupid or often says or does the wrong thing","cn":"蠢人；傻瓜；笨蛋","g":"[countable]","lab":"informal","ex":{"en":"He was acting like a complete jerk.","cn":"他的行为像个十足的笨蛋。"},"pos":"noun"},{"en":"meat that is marinated (= left in a mixture of oil and spices before being cooked) to give it a strong taste and then cooked over a wood fire","cn":"腌制后放在木火上烤的肉","g":"[uncountable]","ex":{"en":"jerk chicken","cn":"烤鸡"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（向某个方向）急拉，猛推；（使）猝然一动","en":"If you jerk something or someone in a particular direction, or they jerk in a particular direction, they move a short distance very suddenly and quickly.","ex":{"en":"Mr Griffin jerked forward in his chair","cn":"格里芬先生坐在椅子上猛地向前一凑。"}},{"pos":"N-COUNT 可数名词","cn":"傻瓜；笨蛋；混蛋","en":"If you call someone a jerk, you are insulting them because you think they are stupid or you do not like them."},{"pos":"","cn":"","en":"相关词组：jerk around jerk off"}]},"examples":[{"en":"He jerked the phone away from her.","cn":"他猛然一下从她那儿把电话抢走。"},{"en":"She got to the door and jerked it open.","cn":"她走到门口，猛然一把将门拉开。"}]},"joke":{"media":{"uk":"media/uk/joke__gb_1.mp3","us":"media/us/joke__us_1.mp3"},"oxford":{"phon":"dʒəʊk","pos":"noun","senses":[{"en":"something that you say or do to make people laugh, for example a funny story that you tell","cn":"笑话；玩笑","ex":{"en":"I can't tell jokes.","cn":"我不会讲笑话。"}},{"en":"a person, thing or situation that is silly or annoying and cannot be taken seriously","cn":"荒唐可笑的人（或事物、局面）；笑料；笑柄","g":"[singular]","lab":"informal","ex":{"en":"This latest pay offer is a joke.","cn":"最近这次提出的报酬简直是开玩笑。"}},{"en":"to say something to make people laugh; to tell a funny story","cn":"说笑话；开玩笑","g":"[intransitive, transitive]","ex":{"en":"She was laughing and joking with the children.","cn":"她同孩子们一起嘻嘻哈哈地说笑话。"},"pos":"verb"},{"en":"to say something that is not true because you think it is funny","cn":"闹着玩；说着玩","g":"[intransitive, transitive]","ex":{"en":"I didn't mean that—I was only joking.","cn":"我并没有那个意思，我只是说着玩儿的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"玩笑；笑话","en":"A joke is something that is said or done to make you laugh, for example a funny story.","ex":{"en":"He debated whether to make a joke about shooting rabbits, but decided against it","cn":"他心里琢磨是否该开个有关打兔子的玩笑，但决定还是算了。"}},{"pos":"VERB 动词","cn":"讲笑话；开玩笑","en":"If you joke, you tell funny stories or say amusing things.","ex":{"en":"She would joke about her appearance","cn":"她会拿自己的长相开玩笑。"}},{"pos":"N-COUNT 可数名词","cn":"恶作剧；捉弄人的玩笑","en":"A joke is something untrue that you tell another person in order to amuse yourself.","ex":{"en":"It was probably just a joke to them, but it wasn't funny to me.","cn":"对他们而言，那可能仅仅是个恶作剧，但对我来说，它一点也不好笑。"}},{"pos":"VERB 动词","cn":"开玩笑；搞恶作剧","en":"If you joke, you tell someone something that is not true in order to amuse yourself.","ex":{"en":"Don't get defensive, Charlie. I was only joking","cn":"别这么大戒心，查理。我只不过是开开玩笑。"}},{"pos":"N-SING 单数名词","cn":"荒唐可笑的事（或人）；笑料；笑柄","en":"If you say that something or someone is a joke, you think they are ridiculous and do not deserve respect.","ex":{"en":"It's ridiculous, it's pathetic, it's a joke","cn":"这真荒谬，简直是可悲、可笑。"}},{"pos":"PHRASE 短语","cn":"（恼人或令人担心的事）不可理喻，使人无法接受","en":"If you say that an annoying or worrying situation is beyond a joke, you are emphasizing that it is worse than you think is fair or reasonable.","ex":{"en":"Giving an arsonist a lighter is beyond a joke","cn":"把打火机交给纵火犯简直是不可理喻。"}},{"pos":"PHRASE 短语","cn":"拿（严肃或悲惨的事情）开玩笑；对…一笑置之","en":"If you make a joke of something, you laugh at it even though it is in fact rather serious or sad.","ex":{"en":"I wish I had your courage, Michael, to make a joke of it like that.","cn":"我真希望能有你那样的勇气，迈克尔，能把事情那么一笑置之。"}},{"pos":"PHRASE 短语","cn":"不是轻而易举的事；不是闹着玩的","en":"If you describe a situation as no joke, you are emphasizing that it is very difficult or unpleasant.","ex":{"en":"Two hours on a bus is no joke, is it?","cn":"在公交车上坐上两个小时可不轻松，对吧？"}},{"pos":"PHRASE 短语","cn":"对…开玩笑；戏弄","en":"If you say that the joke is on a particular person, you mean that they have been made to look very foolish by something.","ex":{"en":"'For once,' he said, 'the joke's on me. And it's not very funny.'","cn":"“他说：“这一次玩笑反而开到自己身上来了。这一点儿也不好玩。”"}},{"pos":"PHRASE 短语","cn":"开不起玩笑；经不起玩笑话","en":"If you say that someone cannot take a joke, you are criticizing them for getting upset or angry at something you think is funny.","ex":{"en":"'What's the matter with you, Simon?' Curly said. 'Can't you take a joke?'","cn":"“西蒙，你怎么回事？”柯利说。“你难道开不起玩笑么？”"}},{"pos":"CONVENTION 惯用语","cn":"（用于表示吃惊或认为不可理喻）你一定是在开玩笑吧","en":"You say you're joking or you must be joking to someone when they have just told you something that is so surprising or unreasonable that you find it difficult to believe.","ex":{"en":"You're joking. Are you serious?","cn":"你准是在开玩笑。你是认真的吗？"}}]},"examples":[{"en":"‘I cooked it myself, so be careful!’ he joked. “","cn":"我亲自下厨做的，所以要小心点哟！”他开玩笑说。"},{"en":"No way am I doing that. You must be joking!","cn":"我决不可能做那样的事。你一定是在开玩笑吧！"}]},"juniper":{"oxford":{"phon":"ˈdʒuːnɪpə(r)","pos":"noun","senses":[{"en":"a bush or small tree with purple berries that are used in medicine and to add taste to gin","cn":"刺柏，桧柏（有些种的浆果可作药用和给杜松子酒调味）"},{"en":"a first name for girls","cn":"朱尼珀（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"刺柏，桧（其紫色浆果可用于烹饪和制药）","en":"A juniper is an evergreen bush with purple berries which can be used in cooking and medicine."}]},"media":{"uk":"media/uk/juniper__gb_1.mp3","us":"media/us/juniper__us_1.mp3"}},"jay":{"media":{"uk":"media/uk/jay__gb_1.mp3","us":"media/us/jay__us_1.mp3"},"oxford":{"phon":"dʒeɪ","pos":"noun","senses":[{"en":"a European bird of the crow family, with bright feathers and a noisy call","cn":"松鸦（见于欧洲，羽毛鲜艳，喜大声鸣叫）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"松鸦（见于欧亚）","en":"In Europe and Asia, a jay is a brownish-pink bird with blue and black wings."},{"pos":"N-COUNT 可数名词","cn":"北美蓝樫鸟（见于北美洲，羽毛呈亮蓝色）","en":"In North America, a jay is a bird with bright blue feathers."}]}},"john":{"media":{"uk":"media/uk/john__gb_1.mp3","us":"media/us/john__us_1.mp3"},"oxford":{"phon":"dʒɒn","pos":"noun","senses":[{"en":"a toilet","cn":"厕所；卫生间"},{"en":"a first name for boys","cn":"约翰（男子名）","pos":""},{"en":"(1167-1216) the king of England from 1199 to 1216. He was the youngest son of Henry II and became king after the death of his brother Richard I, having previously tried to take power from him. He was not a popular or successful king. He lost most of the English land in France, quarrelled with the Church, and was forced by his barons in 1215 to sign the Magna Carta, which limited his royal powers. He is the subject of King John, an early play by Shakespeare.","cn":"约翰：（1167-1216）从1199年到1216年的英格兰国王。他是亨利二世的小儿子，在其兄弟理查德一世去世后成为国王，此前曾试图从他手中夺取政权。他不是一个受欢迎或成功的国王。他在法国失去了大部分英国土地，与教会争吵，并在1215年被男爵逼迫签署《大宪章》，这限制了他的王权。他是莎士比亚早期戏剧约翰·金的主题。","pos":""}]}},"job":{"media":{"uk":"media/uk/job__gb_1.mp3","us":"media/us/job__us_1.mp3"},"oxford":{"phon":"dʒɒb","pos":"noun","senses":[{"en":"work for which you receive regular payment","cn":"工作；职业；职位","lab":"especially British English","sc":"paid work","ex":{"en":"I don't have a job at present.","cn":"我现在没有工作。"}},{"en":"a particular task or piece of work that you have to do","cn":"（一项）任务；（一件）工作，活儿，事情","sc":"task","ex":{"en":"I've got various jobs around the house to do.","cn":"我在家里有各种各样的活儿要干。"}},{"en":"a responsibility or duty","cn":"责任；职责","g":"[usually singular]","lab":"rather informal","sc":"duty","ex":{"en":"He said he wouldn't do it because it wasn't his job.","cn":"他说他不愿意做，因为那不是他的职责。"}},{"en":"a crime, especially stealing","cn":"犯罪行为（尤指偷窃）","lab":"informal","sc":"crime","ex":{"en":"a bank job","cn":"银行抢劫案"}},{"en":"a particular kind of thing","cn":"东西；物件","lab":"informal","sc":"object","ex":{"en":"It's real wood—not one of those plastic jobs.","cn":"这是实木的，不是那种塑料产品。"}},{"en":"an item of work that is done by a computer as a single unit","cn":"作业（计算机批处理任务中的基本单位）","sc":"computing","ex":{"en":"The job can be processed overnight.","cn":"这个活儿连夜就可以处理完。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工作；职业；职位","en":"A job is the work that someone does to earn money.","ex":{"en":"Once I'm in America I can get a job","cn":"我一到美国就能找到工作。"}},{"pos":"N-COUNT 可数名词","cn":"（一项）任务；（一份）工作，活儿","en":"A job is a particular task.","ex":{"en":"He said he hoped that the job of putting together a coalition wouldn't take too much time","cn":"他说他希望结成联盟的工作不会耗时太久。"}},{"pos":"N-COUNT 可数名词","cn":"职责；责任；作用","en":"The job of a particular person or thing is their duty or function.","ex":{"en":"Their main job is to preserve health rather than treat illness","cn":"它们的主要功效是保健而非治病。"}},{"pos":"N-SING 单数名词","cn":"（干得出色的）活儿","en":"If you say that someone is doing a good job, you mean that they are doing something well. In British English, you can also say that they are making a good job of something.","ex":{"en":"We could do a far better job of managing it than they have","cn":"我们会比他们经营得好得多。"}},{"pos":"N-SING 单数名词","cn":"难做的工作；非常费力的事","en":"If you say that you have a job doing something, you are emphasizing how difficult it is.","ex":{"en":"He may have a hard job selling that argument to investors","cn":"他可能得磨破嘴皮才能让投资者接受那个观点。"}},{"pos":"PHRASE 短语","cn":"为有关系的人安排的职位","en":"If you refer to work as jobs for the boys, you mean that the work is unfairly given to someone's friends, supporters, or relations, even though they may not be the best qualified people to do it.","ex":{"en":"The Party has been accused of creating a 'jobs for the boys' system of government.","cn":"该党被指责实行“任人唯亲”的政府用人机制。"}},{"pos":"PHRASE 短语","cn":"正想要的东西；求之不得的东西","en":"If you say that something is just the job, you mean that it is exactly what you wanted or needed.","ex":{"en":"Not only is it just the job for travelling, but it's handy for groceries too.","cn":"它不仅非常适合于旅行，而且用来日常购物也很方便。"}},{"pos":"PHRASE 短语","cn":"在工作；在干活儿；在工作岗位上","en":"If someone is on the job, they are actually doing a particular job or task.","ex":{"en":"The top pay scale after five years on the job would reach $5.00 an hour","cn":"在这个岗位干上5年后，最高薪酬可达每小时5美元。"}},{"pos":"","cn":"","en":"it's a good job→see: ; the job in hand→see: ;"}]},"examples":[{"en":"You need the patience of Job to deal with some of our customers.","cn":"和我们的一些顾客打交道需要有极大的耐心。"},{"en":"Do you enjoy your job?","cn":"你喜欢自己的工作吗？"}]},"justify":{"media":{"uk":"media/uk/justify__gb_1.mp3","us":"media/us/justify__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪfaɪ","pos":"verb","senses":[{"en":"to show that somebody/something is right or reasonable","cn":"证明…正确（或正当、有理）","ex":{"en":"How can they justify paying such huge salaries?","cn":"他们怎能证明付这么大笔薪金是正当的呢？"}},{"en":"to give an explanation or excuse for something or for doing something","cn":"对…作出解释；为…辩解（或辩护）","ex":{"en":"The senator made an attempt to justify his actions.","cn":"参议员试图证明他的行为是合理的。"}},{"en":"to arrange lines of printed text so that one or both edges are straight","cn":"将（打印的字行）调整为边缘对齐","lab":"specialist"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"证明（决定、行为或想法）正当；表明…必要","en":"To justify a decision, action, or idea means to show or prove that it is reasonable or necessary.","ex":{"en":"No argument can justify a war","cn":"任何理由都不能为战争开脱。"}},{"pos":"VERB 动词","cn":"调整（打印文本）；使齐行；使每行排齐","en":"To justify printed text means to adjust the spaces between the words so that each line of type is exactly the same length.","ex":{"en":"Click on this icon to align or justify text.","cn":"点击这个图标使文本排齐。"}}]},"examples":[{"en":"How can they justify paying such huge salaries?","cn":"他们怎能证明付这么大笔薪金是正当的呢？"},{"en":"Her success had justified the faith her teachers had put in her.","cn":"她的成功证明了老师对她的信任是正确的。"}]},"justification":{"oxford":{"phon":"ˌdʒʌstɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"a good reason why something exists or is done","cn":"正当理由","ex":{"en":"I can see no possible justification for any further tax increases.","cn":"我看不出还能提出什么理由再加税。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"正当理由；合理的解释","en":"A justification for something is an acceptable reason or explanation for it.","ex":{"en":"To me the only justification for a zoo is educational","cn":"对我来说，动物园存在的唯一正当理由是其教育作用。"}}]},"media":{"uk":"media/uk/justification__gb_1.mp3","us":"media/us/justification__us_1.mp3"},"examples":[{"en":"All I can say in justification of her actions is that she was under a lot of pressure at work.","cn":"我唯一能为她的行为辩解的理由是她工作压力很大。"},{"en":"I can see no possible justification for any further tax increases.","cn":"我看不出还能提出什么理由来加税了。"}]},"jesus":{"media":{"uk":"media/uk/jesus__gb_1.mp3","us":"media/us/jesus__us_1.mp3"},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"耶稣；耶稣基督","en":"Jesus or Jesus Christ is the name of the man who Christians believe was the son of God, and whose teachings are the basis of Christianity."},{"pos":"EXCLAM 感叹语","cn":"（用于表示惊讶、震惊或厌烦，可能具冒犯意味）天哪，哎呀","en":"Jesus is used by some people to express surprise, shock, or annoyance. This use could cause offence."}]},"examples":[{"en":"Jesus! That was close!","cn":"天啊﹐好险啊！"}],"oxford":{"phon":"ˈdʒiːzəs","pos":"noun","senses":[{"en":"the man that Christians believe is the son of God and on whose teachings the Christian religion is based","cn":"基督；耶稣基督"}]}},"journal":{"media":{"uk":"media/uk/journal__gb_1.mp3","us":"media/us/journal__us_1.mp3"},"oxford":{"phon":"ˈdʒɜːnl","pos":"noun","senses":[{"en":"a newspaper or magazine that deals with a particular subject or profession","cn":"（某学科或行业的）报纸，刊物，杂志","ex":{"en":"a scientific/an academic journal","cn":"科学／学术刊物"}},{"en":"used in the title of some newspapers","cn":"（用于报纸名）…报","ex":{"en":"the Wall Street Journal","cn":"《华尔街日报》"}},{"en":"a written record of the things you do, see, etc. every day","cn":"日志；日记","ex":{"en":"He kept a journal of his travels across Asia.","cn":"他把自己的亚洲之行记录下来了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指某专门学科的）杂志，刊物","en":"A journal is a magazine, especially one that deals with a specialized subject.","ex":{"en":"All our results are published in scientific journals.","cn":"我们的研究结果全都发表在科学刊物上了。"}},{"pos":"N-COUNT 可数名词","cn":"日报，周报，…报（常用于报纸名称中）","en":"A journal is a daily or weekly newspaper. The word journal is often used in the name of the paper.","ex":{"en":"He was a newspaperman for The New York Times and some other journals.","cn":"他是个记者，为《纽约时报》和其他一些报刊撰稿。"}},{"pos":"N-COUNT 可数名词","cn":"日记；日志","en":"A journal is an account which you write of your daily activities.","ex":{"en":"Sara confided to her journal","cn":"萨拉在日记中倾诉心事。"}}]},"examples":[{"en":"He kept a journal of his travels across Asia.","cn":"他把自己的亚洲之行记录下来了。"},{"en":"a scientific/trade journal","cn":"科学/行业杂志"}]},"jump":{"media":{"img":["media/pic/equestriansports_comp.jpg","media/thumb/showjumping.jpg"],"uk":"media/uk/jump__gb_1.mp3","us":"media/us/jump__us_1.mp3"},"oxford":{"phon":"dʒʌmp","pos":"verb","senses":[{"en":"to move quickly off the ground or away from a surface by pushing yourself with your legs and feet","cn":"跳；跃；跳跃","g":"[intransitive]","sc":"move off/to ground","ex":{"en":"‘Quick, jump!’ he shouted.","cn":"“赶快，跳！”他大声叫道。"}},{"en":"to pass over something by jumping","cn":"跳过；跃过；跨越","g":"[intransitive, transitive]","sc":"pass over something","ex":{"en":"He jumped over the wall to get away.","cn":"他跳墙逃跑。"}},{"en":"to move quickly and suddenly","cn":"突然快速移动","g":"[intransitive]","sc":"move quickly","ex":{"en":"He jumped to his feet when they called his name.","cn":"他们叫到他的名字时他一下子就站了起来。"}},{"en":"to make a sudden movement because of surprise, fear or excitement","cn":"（因吃惊、害怕或激动而）猛地一动，突然一跳","g":"[intransitive]","sc":"move quickly","ex":{"en":"A loud bang made me jump.","cn":"砰的一声巨响吓我一跳。"}},{"en":"to rise suddenly by a large amount","cn":"突升；猛涨；激增","g":"[intransitive]","sc":"increase","ex":{"en":"Prices jumped by 60% last year.","cn":"去年，物价暴涨 60%。"}},{"en":"to change suddenly from one subject to another","cn":"突然改变，突然转换（话题、题目）","g":"[intransitive]","sc":"change suddenly","ex":{"en":"I couldn't follow the talk because he kept jumping about from one topic to another.","cn":"我听不明白他的讲话，因为他老是转换话题。"}},{"en":"to leave out something and pass to a further point or stage","cn":"略去；略过；跳过","g":"[transitive]","sc":"leave out","ex":{"en":"You seem to have jumped several steps in the argument.","cn":"你在论证中似乎略去了好几个步骤。"}},{"en":"to move suddenly and unexpectedly, especially out of the correct position","cn":"突然跳出正常位置；意外地离开正常位置","g":"[intransitive]","sc":"of machine/device","ex":{"en":"The needle jumped across the dial.","cn":"指针突然从刻度盘的一端跳到另一端。"}},{"en":"to attack somebody suddenly","cn":"突然袭击（某人）；猛地扑向（某人）","g":"[transitive, intransitive]","lab":"informal","sc":"attack","ex":{"en":"The thieves jumped him in a dark alleyway.","cn":"一伙盗贼在一条漆黑的小巷里突然扑向他。"}},{"en":"to get on a vehicle very quickly, especially in a way that is dangerous or illegal","cn":"跳上（车）（尤指行为危险或违法）","g":"[transitive]","lab":"North American English","sc":"vehicle","ex":{"en":"to jump a bus","cn":"跳上公共汽车"}},{"en":"to start the engine of a car by connecting the battery to the battery of another car with jump leads","cn":"用跨接引线启动（汽车发动机）","lab":"North American English","sc":"vehicle"},{"en":"to put a lot of energy into starting a process or an activity or into making it start more quickly","cn":"全力启动；加快开展","lab":"North American English","sc":"vehicle"},{"en":"to be very lively","cn":"欢跃；雀跃","g":"[intransitive]","lab":"informal","sc":"be lively","ex":{"en":"The bar's jumping tonight.","cn":"今晚酒吧里气氛活跃。"}},{"en":"an act of jumping","cn":"跳；跃；跳跃","sc":"movement","ex":{"en":"to do a parachute jump","cn":"跳伞"},"pos":"noun"},{"en":"a barrier like a narrow fence that a horse or a runner has to jump over in a race or competition","cn":"（比赛中需跳过的）障碍物","sc":"barrier","ex":{"en":"The horse fell at the last jump.","cn":"那匹马在跨越最后一个障碍物时跌倒了。"},"pos":"noun"},{"en":"a sudden increase in amount, price or value","cn":"突升；猛涨；激增","sc":"increase","ex":{"en":"unusually large price jumps","cn":"非同寻常的大幅度涨价"},"pos":"noun"},{"en":"a large or sudden change","cn":"巨变；突变","sc":"change","ex":{"en":"Is he good enough to make the jump into Formula One?","cn":"他是否足够优秀，可以跳级进入一级方程式？"},"pos":"noun"},{"en":"a sudden movement caused by shock or surprise","cn":"（受惊吓引起的）猛的一动，突然一跳","sc":"sudden movement","ex":{"en":"I sat up with a jump.","cn":"我惊得一下子坐了起来。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跳；跃；跳跃","en":"If you jump, you bend your knees, push against the ground with your feet, and move quickly upwards into the air.","ex":{"en":"I jumped over the fence","cn":"我跳过了栅栏。"}},{"pos":"VERB 动词","cn":"跳下；跃出","en":"If you jump from something above the ground, you deliberately push yourself into the air so that you drop towards the ground.","ex":{"en":"He jumped out of a third-floor window","cn":"他从3楼的窗户跳了出去。"}},{"pos":"VERB 动词","cn":"跳过，跃过，跨越（栅栏等）","en":"If you jump something such as a fence, you move quickly up and through the air over or across it.","ex":{"en":"He jumped the first fence beautifully.","cn":"他轻松地跨过第一道栏。"}},{"pos":"VERB 动词","cn":"快速移动；一跃而起","en":"If you jump somewhere, you move there quickly and suddenly.","ex":{"en":"Adam jumped from his seat at the girl's cry","cn":"女孩儿一哭，亚当立即从座位上跳了起来。"}},{"pos":"VERB 动词","cn":"（因害怕或吃惊）猛地一跳，突然一跳","en":"If something makes you jump, it makes you make a sudden movement because you are frightened or surprised.","ex":{"en":"The phone shrilled, making her jump.","cn":"刺耳的电话铃响了起来，把她吓了一跳。"}},{"pos":"VERB 动词","cn":"（数量或水平）突升，激增","en":"If an amount or level jumps, it suddenly increases or rises by a large amount in a short time.","ex":{"en":"Sales jumped from $94 million to over $101 million","cn":"销售额从9, 400万美元激增到了1.0 1亿美元。"}},{"pos":"VERB 动词","cn":"插（队）；不按顺序排（队）","en":"If someone jumps a queue, they move to the front of it and are served or dealt with before it is their turn.","ex":{"en":"The prince refused to jump the queue for treatment at the local hospital.","cn":"王子在本地医院候诊时拒绝插队。"}},{"pos":"VERB 动词","cn":"突然袭击；出其不意地攻击","en":"If someone jumps on you or jumps you, they attack you suddenly or unexpectedly.","ex":{"en":"A week later, the same guys jumped on me on our own front lawn","cn":"一个星期后，同一伙人又在我们家门口的草坪上袭击了我。"}},{"pos":"VERB 动词","cn":"迫不及待地接受，欣然应承（建议或机会）","en":"If you jump at an offer or opportunity, you accept it quickly and eagerly.","ex":{"en":"Members of the public would jump at the chance to become part owners of the corporation.","cn":"一些公众会迫不及待地想要抓住机会成为这家公司的持股人。"}},{"pos":"VERB 动词","cn":"毫不犹豫地批评；立即责备","en":"If someone jumps on you, they quickly criticize you if you do something that they do not approve of.","ex":{"en":"A lot of people jumped on me about that, you know.","cn":"你知道，那件事让很多人逮着机会批评我。"}},{"pos":"PHRASE 短语","cn":"比…占先；胜过；优于","en":"If you get a jump on something or someone or get the jump on them, you gain an advantage over them.","ex":{"en":"Helicopters helped fire crews get a jump on the blaze","cn":"直升机帮助消防队员控制住了火势。"}},{"pos":"PHRASE 短语","cn":"非常激动；欣喜若狂；暴跳如雷","en":"If you say that someone is jumping up and down, you mean they are very excited, happy, or angry about something.","ex":{"en":"I don't think a lot of people will jump up and down and say 'thank heavens'..","cn":"我并不认为很多人会欣喜若狂地说“感谢上帝”。"}},{"pos":"","cn":"","en":"to jump on the bandwagon→see: ; to jump bail→see: ; to jump to a conclusion→see: ; to jump the gun→see: ; to jump for joy→see: ; to jump out of one's skin→see: ;"},{"pos":"","cn":"","en":"相关词组：jump in jump out"}]},"examples":[{"en":"The story then jumps from her childhood in New York to her first visit to London.","cn":"故事接着从她在纽约的童年一下子转到她第一次去伦敦。"},{"en":"Before she could reply Peter jumped in with an objection.","cn":"她还没来得及回答，彼得就迫不及待地表示反对。"}]},"jet":{"media":{"uk":"media/uk/jet__gb_1.mp3","us":"media/us/jet__us_1.mp3"},"oxford":{"phon":"dʒet","pos":"noun","senses":[{"en":"a plane driven by jet engines","cn":"喷气式飞机","g":"[countable]","ex":{"en":"a jet aircraft/fighter/airliner","cn":"喷气式飞机／战斗机／客机"}},{"en":"a strong narrow stream of gas, liquid or flame that comes very quickly out of a small opening. The opening is also called a jet.","cn":"喷射流；喷射口；喷嘴","g":"[countable]","ex":{"en":"The pipe burst and jets of water shot across the room.","cn":"管子爆裂，一股股水从屋子这头喷到那头。"}},{"en":"a hard black mineral that can be polished and is used in jewellery","cn":"煤玉；黑玉；黑色大理石；贝褐碳","g":"[uncountable]","ex":{"en":"jet beads","cn":"黑玉珠"}},{"en":"to fly somewhere in a plane","cn":"乘坐飞机旅行","ex":{"en":"They have just jetted off for a honeymoon in New York.","cn":"他们刚刚飞往纽约度蜜月。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"喷气式飞机","en":"A jet is an aircraft that is powered by jet engines.","ex":{"en":"Her private jet landed in the republic on the way to Japan","cn":"她的私人喷气式飞机在前往日本的途中降落在该共和国境内。"}},{"pos":"VERB 动词","cn":"乘坐喷气式飞机飞行","en":"If you jet somewhere, you travel there in a fast plane.","ex":{"en":"He and his wife, Val, will be jetting off on a two-week holiday in America","cn":"他和妻子瓦尔将乘喷气式飞机飞往美国度假两周。"}},{"pos":"N-COUNT 可数名词","cn":"（液体或气体的）喷射流","en":"A jet of liquid or gas is a strong, fast, thin stream of it.","ex":{"en":"A jet of water poured through the windows.","cn":"一股水流从窗口喷涌而入。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"煤玉；黑玉；黑色大理石","en":"Jet is a hard black stone that is used in jewellery."}]},"examples":[{"en":"The pipe burst and jets of water shot across the room.","cn":"管子爆裂，一股股水从屋子这头喷到那头。"},{"en":"The accident happened as the jet was about to take off.","cn":"事故是在喷气式飞机正要起飞时发生的。"}]},"joints":{"oxford":{"phon":"dʒɔɪnt","pos":"adjective","senses":[{"en":"involving two or more people together","cn":"联合的；共同的"},{"en":"a place where two bones are joined together in the body in a way that enables them to bend and move","cn":"关节"}]}},"justified":{"media":{"uk":"media/uk/justified__gb_1.mp3","us":"media/us/justified__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪfaɪd","pos":"adjective","senses":[{"en":"having a good reason for doing something","cn":"（做某事）有正当理由的","ex":{"en":"She felt fully justified in asking for her money back.","cn":"她认为有充分的理由要求退款。"}},{"en":"existing or done for a good reason","cn":"事出有因的；合乎情理的","ex":{"en":"His fears proved justified.","cn":"他的恐惧后来证明是有原因的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（决定、行为或想法）正当的，合理的","en":"If you describe a decision, action, or idea as justified, you think it is reasonable and acceptable.","ex":{"en":"In my opinion, the decision was wholly justified.","cn":"我认为，这个决定完全合理。"}},{"pos":"ADJ 形容词","cn":"（做…）有正当理由的","en":"If you think that someone is justified in doing something, you think that their reasons for doing it are good and valid.","ex":{"en":"He's absolutely justified in resigning. He was treated shamefully.","cn":"他完全有理由辞职。他受到了侮辱。"}}]},"examples":[{"en":"She felt fully justified in asking for her money back.","cn":"她认为有充分的理由要求退款。"},{"en":"His fears proved justified.","cn":"他的恐惧后来证明是有原因的。"}]},"judaism":{"oxford":{"phon":"ˈdʒuːdeɪɪzəm","pos":"noun","senses":[{"en":"the religion of the Jewish people, based mainly on the first five books of the Bible and the Talmud","cn":"犹太教"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"犹太教","en":"Judaism is the religion of the Jewish people. It is based on the Old Testament of the Bible and the Talmud."}]},"media":{"uk":"media/uk/judaism__gb_1.mp3","us":"media/us/judaism__us_1.mp3"},"examples":[{"en":"Judaic tradition","cn":"犹太教传统"}]},"judicial":{"oxford":{"phon":"dʒuˈdɪʃl","pos":"adjective","senses":[{"en":"connected with a court, a judge or legal judgement","cn":"法庭的；法官的；审判的；司法的","ex":{"en":"judicial powers","cn":"司法权"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"司法的；法庭的；审判的","en":"Judicial means relating to the legal system and to judgments made in a court of law.","ex":{"en":"...an independent judicial inquiry","cn":"独立的司法调查"}}]},"media":{"uk":"media/uk/judicial__gb_1.mp3","us":"media/us/judicial__us_1.mp3"},"examples":[{"en":"the judicial process/system","cn":"司法程序/系统"},{"en":"judicial powers","cn":"司法权"}]},"journalism":{"media":{"uk":"media/uk/journalism__gb_1.mp3","us":"media/us/journalism__us_1.mp3"},"oxford":{"phon":"ˈdʒɜːnəlɪzəm","pos":"noun","senses":[{"en":"the work of collecting and writing news stories for newspapers, magazines, radio, television or online news sites; the news stories that are written","cn":"新闻业；新闻工作；新闻报道","ex":{"en":"I'd like a career in journalism.","cn":"我想从事新闻工作。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"新闻工作；新闻业","en":"Journalism is the job of collecting news and writing about it for newspapers, magazines, television, or radio.","ex":{"en":"He began a career in journalism, working for the North London Press Group","cn":"他开始从事新闻工作，为北伦敦报业集团工作。"}}]},"examples":[{"en":"The hospital has been the target of investigative journalism (= journalism that examines an event or situation in order to find out the truth ) .","cn":"这家医院成了调查报道的目标。"},{"en":"a career in journalism","cn":"新闻职业"}]},"jazz":{"oxford":{"phon":"dʒæz","pos":"noun","senses":[{"en":"a type of music with strong rhythms, in which the players often improvise (= make up the music as they are playing), originally created by African American musicians at the beginning of the 20th century","cn":"爵士乐","lab":"British English","ex":{"en":"traditional/modern jazz","cn":"传统／现代爵士乐"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"爵士乐","en":"Jazz is a style of music that was invented by African American musicians in the early part of the twentieth century. Jazz music has very strong rhythms and often involves improvisation.","ex":{"en":"The pub has live jazz on Sundays.","cn":"那家酒馆每周日都有现场爵士乐演奏。"}},{"pos":"","cn":"","en":"相关词组：jazz up"}]},"media":{"uk":"media/uk/jazz__gb_1.mp3","us":"media/us/jazz__us_1.mp3"},"examples":[{"en":"How's it going? You know — love, life and all that jazz.","cn":"怎么样啊？你知道，说的就是爱情、生活以及诸如此类的事情嘛。"},{"en":"It's a jazzed up version of an old tune.","cn":"这是把一段古老的曲调翻新了。"}]},"july":{"media":{"uk":"media/uk/july__gb_1.mp3","us":"media/us/july__us_1.mp3"},"oxford":{"phon":"dʒuˈlaɪ","pos":"noun","senses":[{"en":"the 7th month of the year, between June and August","cn":"七月","lab":"British English","ex":{"en":"She was born in July.","cn":"她出生在七月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"七月","en":"July is the seventh month of the year in the Western calendar.","ex":{"en":"In late July 1914, he and Violet spent a few days with friends near Berwick-upon-Tweed","cn":"1914年7月下旬，他和维奥莱特与几个朋友在特威德河畔贝里克附近度过了几天。"}}]}},"jubilant":{"media":{"uk":"media/uk/jubilant__gb_1.mp3","us":"media/us/jubilant__us_1.mp3"},"oxford":{"phon":"ˈdʒuːbɪlənt","pos":"adjective","senses":[{"en":"feeling or showing great happiness because of a success","cn":"喜气洋洋的；欢欣鼓舞的；欢呼雀跃的","ex":{"en":"The fans were in jubilant mood after the victory.","cn":"胜利后，球迷们心情愉悦。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因为成功而）欢欣鼓舞的，欣喜若狂的","en":"If you are jubilant, you feel extremely happy because of a success.","ex":{"en":"Ferdinand was jubilant after making an impressive comeback from a month on the injured list.","cn":"费迪南德受伤休养了一个月，重新归队后表现非常出色，他简直高兴极了。"}}]},"examples":[{"en":"Radicals were jubilant at getting rid of him.","cn":"激进分子因为除掉了他而欣喜若狂。"},{"en":"The fans were in jubilant mood as they left the stadium.","cn":"球迷们离开体育场时兴高采烈。"}]},"jammed":{"media":{"uk":"media/uk/jammed__gb_1.mp3","us":"media/us/jammed__us_1.mp3"},"oxford":{"phon":"dʒæmd","pos":"adjective","senses":[{"en":"not able to move","cn":"动弹不得；卡住了","g":"[not before noun]","ex":{"en":"I can't get the door open—it's completely jammed.","cn":"我打不开门，它卡死了。"}},{"en":"very full; crowded","cn":"挤满的；塞满的；拥挤不堪的","lab":"especially North American English","ex":{"en":"Hundreds more people were waiting outside the jammed stadium.","cn":"还有数百人在拥挤不堪的体育场外等候。"}}]},"examples":[{"en":"Hundreds more people were waiting outside the jammed stadium.","cn":"还有数百人在拥挤不堪的体育场外等候。"},{"en":"I can't get the door open — it's completely jammed.","cn":"我打不开门 — 卡死了。"}]},"junction":{"media":{"uk":"media/uk/junction__gb_1.mp3","us":"media/us/junction__us_1.mp3"},"oxford":{"phon":"ˈdʒʌŋkʃn","pos":"noun","senses":[{"en":"the place where two or more roads or railway lines meet","cn":"（公路或铁路的）交叉路口，汇合处，枢纽站","lab":"especially British English","ex":{"en":"It was near the junction of City Road and Old Street.","cn":"那是在城市路与老街的交叉路口附近。"}},{"en":"a place where two or more cables, rivers or other things meet or are joined","cn":"（电缆的）主接点；（河流的）汇合处；接合点","ex":{"en":"a telephone junction box","cn":"电话分线盒"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（公路的）交叉路口；（公路或铁路的）汇合处，枢纽站","en":"A junction is a place where roads or railway lines join.","ex":{"en":"Follow the road to a junction and turn left","cn":"沿着这条路到交叉路口，然后左转。"}}]},"examples":[{"en":"It was near the junction of City Road and Old Street.","cn":"那是在城市路与老街的交叉路口附近。"},{"en":"Come off the motorway at junction 6.","cn":"在 6 号交叉路口驶离高速公路。"}]},"jewelry":{"oxford":{"phon":"ˈdʒuːəlri","pos":"noun","senses":[{"en":"objects such as rings and necklaces that people wear as decoration","cn":"珠宝；首饰"}]}},"jokes":{"oxford":{"phon":"dʒəʊk","pos":"noun","senses":[{"en":"something that you say or do to make people laugh, for example a funny story that you tell","cn":"笑话；玩笑"},{"en":"( informal ) a person, thing or situation that is ridiculous or annoying and cannot be taken seriously","cn":"荒唐可笑的人（或事物）；笑料；笑柄"}]},"media":{"uk":"media/uk/joke__gb_1.mp3","us":"media/us/joke__us_1.mp3"}},"joneses":{"oxford":{"phon":"ˈdʒəʊnzɪz","pos":"noun","senses":[{"en":"( informal, often disapproving ) to try to have all the possessions and social achievements that your friends and neighbours have （","cn":"与朋友和邻居在物质和社会成就方面）攀比，比富有，比排场，比阔气"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"攀比；比排场；比阔气","en":"If you say that someone is keeping up with the Joneses, you mean that they are doing something in order to show that they have as much money as other people, rather than because they really want to do it.","ex":{"en":"Many people were holding down three jobs just to keep up with the Joneses.","cn":"许多人同时做3份工作只不过是为了和别人攀比。"}}]},"media":{"uk":"media/uk/joneses__gb_1.mp3","us":"media/us/joneses__us_1.mp3"}},"jogging":{"media":{"img":["media/pic/keepingfit_comp.jpg","media/thumb/jogging.jpg"],"uk":"media/uk/jogging__gb_1.mp3","us":"media/us/jogging__us_1.mp3"},"oxford":{"phon":"ˈdʒɒɡɪŋ","pos":"noun","senses":[{"en":"the activity of running slowly and steadily as a form of exercise","cn":"慢跑锻炼","lab":"British English","ex":{"en":"to go jogging","cn":"慢跑锻炼"}}]},"examples":[{"en":"to go jogging","cn":"慢跑锻炼"}]},"just":{"media":{"uk":"media/uk/just__gb_1.mp3","us":"media/us/just__us_1.mp3"},"oxford":{"phon":"dʒʌst","pos":"adverb","senses":[{"en":"only","cn":"仅仅；只不过","ex":{"en":"There is just one method that might work.","cn":"只有一个方法可能起作用。"}},{"en":"simply","cn":"只是；仅仅是","lab":"informal","ex":{"en":"It was just an ordinary day.","cn":"那只是普普通通的一天。"}},{"en":"by a small amount","cn":"刚好；差一点就不；勉强","ex":{"en":"You've just missed her.","cn":"你刚好错过了她。"}},{"en":"used to say that you/somebody did something or something happened very recently","cn":"刚才；方才","lab":"especially North American English","ex":{"en":"I've just heard the news.","cn":"我刚听到这个消息。"}},{"en":"at this/that moment; now","cn":"此时；那时；眼下；现在","ex":{"en":"I'm just finishing my book.","cn":"眼下我正在完成我的一本书。"}},{"en":"exactly","cn":"正好；恰好","lab":"British English","ex":{"en":"This jacket is just my size.","cn":"这件夹克正合我的尺码。"}},{"en":"at the same moment as","cn":"正当…时","ex":{"en":"The clock struck six just as I arrived.","cn":"我到达时，时钟正敲六点。"}},{"en":"no less than; equally","cn":"不亚于；同样","ex":{"en":"She's just as smart as her sister.","cn":"她与她姐姐一样聪明。"}},{"en":"going to do something only a few moments from now or then","cn":"正要；正准备；马上就要","ex":{"en":"The water's just about to boil.","cn":"水马上就要开了。"}},{"en":"really; completely","cn":"真正地；确实；完全","lab":"informal","ex":{"en":"The food was just wonderful!","cn":"那吃的实在是好极了！"}},{"en":"used in orders to get somebody’s attention, give permission, etc.","cn":"（引起注意、表示允许等）请，就","ex":{"en":"Just listen to what I'm saying, will you!","cn":"你就听我说好吗？"}},{"en":"used to make a polite request, excuse, etc.","cn":"（提出请求、表示歉意等）请","ex":{"en":"Could you just help me with this box, please?","cn":"请帮我搬一搬这箱子好吗？"}},{"en":"used to show a slight possibility that something is true or will happen","cn":"（表示稍有可能）可能，也许","ex":{"en":"Try asking Mike—he might just know the answer.","cn":"问问迈克吧，没准儿他知道答案。"}},{"en":"used to agree with somebody","cn":"（表示赞同）","ex":{"en":"‘He's very pompous.’ ‘Isn't he just?’","cn":"“他很自负。”“可不是吗？”"}},{"en":"that most people consider to be morally fair and reasonable","cn":"公正的；正义的；正当的；合理的","ex":{"en":"a just decision/law/society","cn":"公正的判决／法律／社会"},"pos":"adjective"},{"en":"people who are just","cn":"正直的人；公正的人","g":"[plural]","pos":"adjective"},{"en":"appropriate in a particular situation","cn":"合适的；恰当的","ex":{"en":"a just reward/punishment","cn":"应有的报偿／惩罚"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"刚才；方才；刚刚","en":"You use just to say that something happened a very short time ago, or is starting to happen at the present time. For example, if you say that someone has just arrived, you mean that they arrived a very short time ago.","ex":{"en":"I've just bought a new house","cn":"我刚买了栋新房子。"}},{"pos":"ADV 副词","cn":"正在；正要；正准备","en":"If you say that you are just doing something, you mean that you are doing it now and will finish it very soon. If you say that you are just about to do something, or just going to do it, you mean that you will do it very soon.","ex":{"en":"I'm just making the sauce for the cauliflower","cn":"我正在弄花椰菜的调味汁呢。"}},{"pos":"ADV 副词","cn":"（用于强调）正，就，恰恰（在某个时刻）","en":"You can use just to emphasize that something is happening at exactly the moment of speaking or at exactly the moment that you are talking about.","ex":{"en":"Randall would just now be getting the Sunday paper","cn":"兰德尔这个时候应该正在拿周日的报纸。"}},{"pos":"ADV 副词","cn":"（尤用于纠正错误的观点）只是，仅仅是","en":"You use just to indicate that something is no more important, interesting, or difficult, for example, than you say it is, especially when you want to correct a wrong idea that someone may get or has already got.","ex":{"en":"It's just a suggestion","cn":"这只是个建议。"}},{"pos":"ADV 副词","cn":"（用于强调所谈的只是一小部分而非全部）仅仅是，只不过是","en":"You use just to emphasize that you are talking about a small part, not the whole of an amount.","ex":{"en":"That's just one example of the kind of experiments you can do","cn":"这只不过是你可以做的各种试验中的一例罢了。"}},{"pos":"ADV 副词","cn":"（用于强调数量少或时间短）只是，仅仅","en":"You use just to emphasize how small an amount is or how short a length of time is.","ex":{"en":"Stephanie and David redecorated a room in just three days","cn":"斯蒂法妮和戴维仅仅花了3天就把一个房间装饰一新。"}},{"pos":"ADV 副词","cn":"（用于动词前表示事情的结果糟糕，很可能导致局面恶化）只（会），只不过","en":"You can use just in front of a verb to indicate that the result of something is unfortunate or undesirable and is likely to make the situation worse rather than better.","ex":{"en":"Leaving like I did just made it worse","cn":"像我那样一走了之只会让事情变得更糟。"}},{"pos":"ADV 副词","cn":"（用于表示情况在很小的程度上属实）刚刚，勉强，差一点就不","en":"You use just to indicate that what you are saying is the case, but only by a very small degree or amount.","ex":{"en":"Her hand was just visible by the light from the sitting room","cn":"借着起居室的灯光，勉强能看见她的手。"}},{"pos":"ADV 副词","cn":"（与might，may和could连用，表示稍有可能）可能，也许","en":"You use just with 'might,' 'may,' and 'could', when you mean that there is a small chance of something happening, even though it is not very likely.","ex":{"en":"It's an old trick but it just might work","cn":"这是个老掉牙的把戏了，不过也许会有用。"}},{"pos":"ADV 副词","cn":"（用于加强语气，表示生气、赞美、肯定等）硬是，就是，简直","en":"You use just to emphasize the following word or phrase, in order to express feelings such as annoyance, admiration, or certainty.","ex":{"en":"She just won't relax","cn":"她就是放松不下来。"}},{"pos":"ADV 副词","cn":"（用于指示、礼貌的请求或表示意图的陈述，用来弱化语气）请，只要，只管…就好了","en":"You use just with instructions, polite requests, or statements of intention, to make your request or statement seem less difficult.","ex":{"en":"Could you just give us a description of your cat?","cn":"能否请您向我们描述一下您的猫？"}},{"pos":"ADV 副词","cn":"请稍候；稍等一下","en":"You use just in expressions such as just a minute and just a moment to ask someone to wait for a short time.","ex":{"en":"'Let me in, Di.' — 'Okay. Just a minute.'","cn":"“让我进来，迪。”——“好的。稍等一下。”"}},{"pos":"ADV 副词","cn":"（用于打断某人，以表示不同意、解释某事或让其保持冷静）稍等一下，且慢","en":"You can use just in expressions such as just a minute and just a moment to interrupt someone, for example in order to disagree with them, explain something, or calm them down.","ex":{"en":"Well, now just a second, I don't altogether agree with the premise.","cn":"嗯，且慢，我并不完全同意这个前提。"}},{"pos":"ADV 副词","cn":"（用于否定附加问句，表示完全赞同）难道不是吗，确实如此","en":"You can use just with negative question tags, for example 'isn't he just?' and 'don't they just!', to say that you agree completely with what has been said.","ex":{"en":"'That's crazy,' I said. 'Isn't it just?' he said","cn":"“那简直是疯了，”我说。“谁说不是呢？”他说。"}},{"pos":"ADV 副词","cn":"（表示完全可以想象）完全，简直","en":"If you say that you can just see or hear something, you mean that it is easy for you to imagine seeing or hearing it.","ex":{"en":"I can just see the nasty suspicious looks I'd be getting from you if we started whispering together","cn":"要是我们开始凑在一起交头接耳，我简直能想象到你那种令人讨厌的怀疑的目光了。"}},{"pos":"ADV 副词","cn":"确切地；精确地","en":"You use just to mean exactly, when you are specifying something precisely or asking for precise information.","ex":{"en":"It is really not clear just why he became a Socialist","cn":"他为何成为社会党人的确切原因实际上还不清楚。"}},{"pos":"ADV 副词","cn":"恰恰是；正是","en":"You use just to emphasize that a particular thing is exactly what is needed or fits a particular description exactly.","ex":{"en":"Kiwi fruit are just the thing for a healthy snack","cn":"猕猴桃作为有益健康的零食是再好不过了。"}},{"pos":"ADV 副词","cn":"正（如）；正（像）","en":"You use just in expressions such as just like ,just as...as, and just the same when you are emphasizing the similarity between two things or two people.","ex":{"en":"Behind the facade they are just like the rest of us","cn":"在那副外表背后，他们和我们大家是完全一样的。"}},{"pos":"PHRASE 短语","cn":"差不多；几乎；近乎","en":"You use just about to indicate that what you are talking about is so close to being the case that it can be regarded as being the case.","ex":{"en":"There are those who believe that Nick Price is just about the best golfer in the world","cn":"有一些人认为尼克·普赖斯几乎就是世界上最优秀的高尔夫球运动员了。"}},{"pos":"PHRASE 短语","cn":"勉强；差一点就不","en":"You use just about to indicate that what you are talking about is in fact the case, but only by a very small degree or amount.","ex":{"en":"I can just about tolerate it at the moment","cn":"当时我差一点就忍受不了了。"}},{"pos":"PHRASE 短语","cn":"（用于表示接近于某一具体数量）几乎，差不多","en":"Just on is used in mentioning an almost exact number or amount.","ex":{"en":"Eve, squinting at the clock, saw it was just on 7 a.m","cn":"伊夫眯着眼瞥了一下钟，看到差不多是早上7点钟。"}},{"pos":"CONVENTION 惯用语","cn":"对极了；正是","en":"Just so is used to agree with or confirm a statement that has been made.","ex":{"en":"'She has a large flat in Mayfair.' — 'Just so.'","cn":"“她在梅费尔有个大公寓。”——“正是。”"}},{"pos":"PHRASE 短语","cn":"严格按照要求的","en":"If things are just so, they are done or arranged exactly as they should be or exactly as someone wants them.","ex":{"en":"I do her hair, and it has to be just so.","cn":"我必须得按她的要求为她做头发。"}},{"pos":"PHRASE 短语","cn":"（用于弱化抱怨、给出建议或理由时的语气）只不过，只是","en":"You use the expression it's just that when you are making a complaint, suggestion, or excuse, so that the person you are talking to will not get annoyed with you.","ex":{"en":"I'm sorry I struck you. I didn't mean to. It's just that I was so mad","cn":"很抱歉我打了你。我不是有意的，只不过我当时气极了。"}},{"pos":"","cn":"","en":"just my luck→see: ; not just→see: ; just now→see: ; only just→see: ; it just goes to show→see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"公正的；正当的；正义的；合理的","en":"If you describe a situation, action, or idea as just, you mean that it is right or acceptable according to particular moral principles, such as respect for all human beings.","ex":{"en":"In a just society there must be a system whereby people can seek redress through the courts","cn":"在一个公正的社会中，一定会有一套人们可以通过法庭寻求赔偿的体制。"}},{"pos":"","cn":"","en":"to get your just deserts→see: ;"}]},"examples":[{"en":"‘Is Mr Burns available?’ ‘Just a second, please, I'll check.’ “","cn":"我可以见伯恩斯先生吗？” “请稍等一会儿，我来查一下。”"},{"en":"‘Can I help you?’ ‘No thanks, I'm just looking. ’ (= in a shop/store) “","cn":"我能为你做点什么吗？” “不用，谢谢，我只是看看。”"}]},"jealous":{"oxford":{"phon":"ˈdʒeləs","pos":"adjective","senses":[{"en":"feeling angry or unhappy because somebody you like or love is showing interest in somebody else","cn":"吃醋的；妒忌的","ex":{"en":"a jealous wife/husband","cn":"好吃醋的妻子／丈夫"}},{"en":"feeling angry or unhappy because you wish you had something that somebody else has","cn":"妒羡的；忌妒的","ex":{"en":"She's jealous of my success.","cn":"她忌妒我的成功。"}},{"en":"wanting to keep or protect something that you have because it makes you feel proud","cn":"珍惜的；爱惜的；精心守护的","ex":{"en":"They are very jealous of their good reputation (= they do not want to lose it).","cn":"他们极为珍惜自己的声誉。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"妒忌的；吃醋的；小心守护的","en":"If someone is jealous, they feel angry or bitter because they think that another person is trying to take a lover or friend, or a possession, away from them.","ex":{"en":"She got insanely jealous and there was a terrible fight.","cn":"她妒忌得发疯，结果是大吵一架。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"妒羡的；羡慕的；忌妒的","en":"If you are jealous of another person's possessions or qualities, you feel angry or bitter because you do not have them.","ex":{"en":"She was jealous of his wealth","cn":"她忌妒他的富有。"}}]},"media":{"uk":"media/uk/jealous__gb_1.mp3","us":"media/us/jealous__us_1.mp3"},"examples":[{"en":"Children often feel jealous when a new baby arrives.","cn":"新生婴儿出世时孩子常常感到忌妒。"},{"en":"He's only talking to her to make you jealous.","cn":"他跟她讲话只是让你妒忌。"}]},"jacket":{"media":{"img":["media/ldoce/img/jacket.jpg","media/pic/coats_jackets_comp.jpg"],"uk":"media/uk/jacket__gb_1.mp3","us":"media/us/jacket__us_1.mp3"},"oxford":{"phon":"ˈdʒækɪt","pos":"noun","senses":[{"en":"a piece of clothing worn on the top half of the body over a shirt, etc. that has arms and fastens down the front; a short, light coat","cn":"夹克衫；短上衣","ex":{"en":"a leather/denim/tweed jacket","cn":"皮／牛仔布／花呢夹克"}},{"en":"a loose paper cover for a book, usually with a design or picture on it","cn":"（书的）护封；书套"},{"en":"an outer cover around a hot water pipe, etc., for example to reduce loss of heat","cn":"（热水管的）保温套，绝热罩"},{"en":"the skin of a baked potato","cn":"烤过的土豆的皮","lab":"British English","ex":{"en":"potatoes baked in their jackets","cn":"带皮烤的土豆"}},{"en":"a stiff paper or thick card cover for a record","cn":"唱片套","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"短上衣；夹克衫","en":"A jacket is a short coat with long sleeves.","ex":{"en":"...a black leather jacket.","cn":"黑色皮夹克"}},{"pos":"N-COUNT 可数名词","cn":"（带皮烤土豆的）土豆皮","en":"Potatoes baked in their jackets are baked with their skin on."},{"pos":"N-COUNT 可数名词","cn":"（书籍的）护封，书套","en":"The jacket of a book is the paper cover that protects the book."},{"pos":"N-COUNT 可数名词","cn":"唱片套","en":"A record jacket is the cover in which a record is kept."}]},"examples":[{"en":"I have to wear a jacket and tie to work.","cn":"我上班得穿短上衣打领带。"},{"en":"a denim/tweed jacket","cn":"斜纹布/花呢夹克衫"}]},"justifiable":{"media":{"uk":"media/uk/justifiable__gb_1.mp3","us":"media/us/justifiable__us_1.mp3"},"oxford":{"phon":"ˌdʒʌstɪˈfaɪəbl","pos":"adjective","senses":[{"en":"existing or done for a good reason, and therefore acceptable","cn":"有理由的；可证明是正当的；情有可原的","ex":{"en":"She took a justifiable pride in her son's achievements.","cn":"她理所当然地为儿子的成就感到自豪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有理由的；无可非议的；情有可原的","en":"An action, situation, emotion, or idea that is justifiable is acceptable or correct because there is a good reason for it.","ex":{"en":"The violence of the revolutionary years was justifiable on the grounds of political necessity.","cn":"出于政治需要，革命年代的暴力行为是情有可原的。"}}]},"examples":[{"en":"The university can be justifiably proud of its record.","cn":"这所大学值得为自己的纪录而自豪。"},{"en":"justifiable pride","cn":"无可非议的自豪感"}]},"jest":{"oxford":{"phon":"dʒest","pos":"noun","senses":[{"en":"something said or done to make people laugh","cn":"笑话；俏皮话；打趣；玩笑","ex":{"en":"He laughed uproariously at his own jest.","cn":"他为自己的玩笑哈哈大笑。"}},{"en":"to say things that are not serious or true, especially in order to make somebody laugh","cn":"开玩笑；说笑话","ex":{"en":"Would I jest about such a thing?","cn":"这种事我会说着玩吗？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"笑话；打趣；玩笑","en":"A jest is something that you say that is intended to be amusing.","ex":{"en":"It was a jest rather than a reproach","cn":"这与其说是责备，还不如说是句玩笑呢。"}},{"pos":"VERB 动词","cn":"说笑话；开玩笑；打趣","en":"If you jest, you tell jokes or say amusing things.","ex":{"en":"He enjoyed drinking and jesting with his cronies","cn":"他喜欢和老朋友喝喝酒、开开玩笑。"}}]},"media":{"uk":"media/uk/jest__gb_1.mp3","us":"media/us/jest__us_1.mp3"},"examples":[{"en":"‘Many a true word is spoken in jest,’ thought Rosie (= people often say things as a joke that are actually true). “","cn":"许多真话都是在玩笑中说出的。”罗西想。"},{"en":"The remark was made half in jest.","cn":"这话是半开玩笑说出的。"}]},"joyfulness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very happy and excited about something that has happened","cn":""},{"en":"to feel extremely happy and confident because you are very successful or because something very good has happened to you","cn":""}]},"examples":[{"en":"Christmas is a joyful occasion for children.","cn":"","src":"ld"}],"media":{"uk":"media/uk/joyfulness__gb_1.mp3","us":"media/us/joyfulness__us_1.mp3"},"oxford":{"phon":"ˈdʒɔɪflnəs","pos":"noun","senses":[{"en":"a feeling of great happiness","cn":"高兴；愉快；喜悦","ex":{"en":"the joyfulness of the occasion","cn":"场合的欢乐"}}]}},"juggling":{"oxford":{"phon":"ˈdʒʌɡl","pos":"verb","senses":[{"en":"to throw a set of three or more objects such as balls into the air and catch and throw them again quickly, one at a time","cn":"玩杂耍（连续向空中抛接多个物体）"},{"en":"to try to deal with two or more important jobs or activities at the same time so that you can fit all of them into your life","cn":"尽力同时应付（两个或更多的重要工作或活动）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/juggling1004.mp3","us":"media/ldoce/hwd/ame/c/juggling1004a.mp3","img":["media/ldoce/img/juggling.jpg"]},"examples":[{"en":"It took a lot of juggling and rearrangement of figures before the loan was approved.","cn":"这笔贷款获批之前﹐数额经过了多次调整和修改。"},{"en":"a display of juggling","cn":"杂耍表演"}]},"jackets":{"oxford":{"phon":"ˈdʒækɪt","pos":"noun","senses":[{"en":"a piece of clothing worn on the top half of the body over a shirt, etc. that has sleeves and fastens down the front; a short, light coat","cn":"夹克衫；短上衣"},{"en":"a loose paper cover for a book, usually with a design or picture on it （","cn":"书籍通常带有图案或画面的）护封，书套"}]}},"jungles":{"oxford":{"phon":"ˈdʒʌŋɡl","pos":"noun","senses":[{"en":"an area of tropical forest where trees and plants grow very thickly （","cn":"热带）丛林，密林"},{"en":"an unfriendly or dangerous place or situation, especially one where it is very difficult to be successful or to trust anyone","cn":"尔虞我诈的环境；危险地带"}]}},"jumping":{"oxford":{"phon":"dʒʌmp","pos":"verb","senses":[{"en":"to move quickly off the ground or away from a surface by pushing yourself with your legs and feet","cn":"跳；跃；跳跃"},{"en":"to pass over sth by jumping","cn":"跳过；跃过；跨越"}]}},"jerked":{"oxford":{"phon":"dʒɜːk","pos":"verb","senses":[{"en":"to move or to make sth move with a sudden short sharp movement","cn":"急拉；猛推；猝然一动"},{"en":"( informal ) ( especially NAmE ) to make things difficult for sb, especially by not being honest with them （","cn":"尤指通过不诚实的手段）给某人出难题，为某人设置障碍，为难某人"}]}},"joining":{"oxford":{"phon":"dʒɔɪn","pos":"verb","senses":[{"en":"to fix or connect two or more things together","cn":"连接；接合；联结"},{"en":"if two things or groups join , or if one thing or group joins another, they come together to form one thing or group","cn":"结合；联合；汇合"}]}},"joined":{"oxford":{"phon":"dʒɔɪn","pos":"verb","senses":[{"en":"to fix or connect two or more things together","cn":"连接；接合；联结"},{"en":"if two things or groups join , or if one thing or group joins another, they come together to form one thing or group","cn":"结合；联合；汇合"}]}},"jobs":{"oxford":{"phon":"dʒɒb","pos":"noun","senses":[{"en":"work for which you receive regular payment","cn":"工作；职业；职位"},{"en":"a particular task or piece of work that you have to do （","cn":"一项）任务；（一件）工作，活儿，事情"}]}},"japanese":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"日本的；日本人的；日语的；日本文化的","en":"Japanese means belonging or relating to Japan, or to its people, language, or culture.","ex":{"en":"Japanese firms are looking for a new breed of manager.","cn":"日本企业在寻觅新型管理人才。"}},{"pos":"N-PLURAL 复数名词","cn":"日本人","en":"The Japanese are the people of Japan."},{"pos":"N-UNCOUNT 不可数名词","cn":"日语","en":"Japanese is the language spoken in Japan."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41japanese.mp3","us":"media/ldoce/hwd/ame/0/japanese.mp3"},"examples":[{"en":"a Japanese car","cn":"日本(汽)车"}],"oxford":{"phon":"ˌdʒæpəˈniːz","pos":"noun, adjective","senses":[{"en":"(a person) from Japan","cn":"日本人；日本的；日本人的"}]}},"journals":{"oxford":{"phon":"ˈdʒɜːnl","pos":"noun","senses":[{"en":"a newspaper or magazine that deals with a particular subject or profession （","cn":"某学科或行业的）报纸，刊物，杂志"},{"en":"used in the title of some newspapers （","cn":"用于报纸名）… 报"}]}},"judging":{"oxford":{"phon":"dʒʌdʒ","pos":"noun","senses":[{"en":"a person in a court who has the authority to decide how criminals should be punished or to make legal decisions","cn":"法官；审判员"},{"en":"a person who decides who has won a competition","cn":"裁判员；评判员"}]}},"jutting":{"oxford":{"phon":"dʒʌt","pos":"verb","senses":[{"en":"to stick out further than the surrounding surface, objects, etc; to make sth stick out （","cn":"使）突出，伸出"}]},"media":{"uk":"media/ldoce/hwd/bre/e/jut0205.mp3","us":"media/ldoce/hwd/ame/7/jut.mp3"},"examples":[{"en":"Tall jagged rocks jutted out over the beach.","cn":""},{"en":"She jutted her chin out aggressively as she glowered back at him.","cn":""}]},"jumped":{"oxford":{"phon":"dʒʌmp","pos":"verb","senses":[{"en":"to move quickly off the ground or away from a surface by pushing yourself with your legs and feet","cn":"跳；跃；跳跃"},{"en":"to pass over sth by jumping","cn":"跳过；跃过；跨越"}]}},"jug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（带柄的）罐，壶","en":"A jug is a cylindrical container with a handle and is used for holding and pouring liquids.","ex":{"en":"...a jug of water.","cn":"一壶水"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container with a wide curved opening at the top and a handle, used especially at meals for pouring liquids 〔","cn":"有柄带嘴的〕壶﹐罐"},{"en":"a deep round container with a very narrow opening at the top and a handle, used for holding liquids 〔","cn":"细口带柄的〕大壶﹐大罐"},{"en":"the amount of liquid that a jug will hold","cn":"一壶之量﹐一罐之量"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Many people buy their milk in a jug , a large container with a handle and a small opening at the top."}]},"collocations":{"phrases":["ADJ. measuring | china, earthenware, enamel, enamelled, glass, plastic | cream, milk, water, wine","VERB + JUG fill, pour sth into He filled a jug with juice. | pour, tip She poured a jug of water over his head. | empty, pour sth from/out o","PREP. ~ of a jug of milk"]},"media":{"img":["media/ldoce/img/jug.jpg","media/thumb/jug.jpg"],"uk":"media/ldoce/hwd/bre/8/jug0205.mp3","us":"media/ldoce/hwd/ame/5/jug.mp3"},"examples":[{"en":"She spilled a jug of water.","cn":"她把一罐子水弄洒了。"},{"en":"a five-gallon jug of beer","cn":"五加仑装的啤酒罐"}],"oxford":{"phon":"dʒʌɡ","pos":"noun","senses":[{"en":"a container with a handle and a lip, for holding and pouring liquids","cn":"（有把有嘴的）壶，罐","lab":"British English","ex":{"en":"a milk/water jug","cn":"奶杯；水罐"}},{"en":"a large round container with a small opening and a handle, and usually with a stopper or cap, for holding liquids","cn":"（细口带把的）大罐","lab":"North American English","ex":{"en":"a five-gallon jug of beer","cn":"五加仑装的啤酒罐"}},{"en":"the amount of liquid contained in a jug","cn":"一壶，一罐（的量）","ex":{"en":"She spilled a jug of water.","cn":"她把一罐子水弄洒了。"}},{"en":"an offensive word for a woman’s breasts","cn":"（冒犯语）乳房，奶子","g":"[plural]","lab":"taboo, offensive, slang，，，，"}]}},"joker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"爱开玩笑的人；逗趣的人","en":"Someone who is a joker likes making jokes or doing amusing things.","ex":{"en":"He is, by nature, a joker, a witty man with a sense of fun.","cn":"他天性是个爱开玩笑的人，说话诙谐，很有幽默感。"}},{"pos":"N-COUNT 可数名词","cn":"（纸牌中的）百搭牌，王牌","en":"The joker in a pack of playing cards is the card which does not belong to any of the four suits."},{"pos":"N-COUNT 可数名词","cn":"愚蠢的人；举止危险的人；小丑","en":"You can call someone a joker if you think they are behaving in a stupid or dangerous way.","ex":{"en":"Keep your eye on these jokers, you never know what they will come up with.","cn":"留神那些活宝，你永远也不知道他们会想出什么样的主意。"}},{"pos":"PHRASE 短语","cn":"与众不同的人（或事物）；难以捉摸的人（或事物）","en":"If you describe someone or something as the joker in the pack, you mean that they are different from the other people or things in their group, and can be unpredictable."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a professional entertainer who makes people laugh","cn":""},{"en":"an intelligent person who is good at being funny in clever or original ways","cn":""},{"en":"someone who does something in order to confuse or trick someone else, to make other people laugh","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/joker0205.mp3","us":"media/ldoce/hwd/ame/c/joker.mp3"},"examples":[{"en":"Look at that joker – he’s doing 25 miles an hour at the most.","cn":"瞧那个傻瓜﹐他的时速最多25英里。"}],"oxford":{"phon":"ˈdʒəʊkə(r)","pos":"noun","senses":[{"en":"a person who likes making jokes or doing silly things to make people laugh","cn":"爱开玩笑的人；爱说笑话的人","ex":{"en":"He’s always been a bit of a joker.","cn":"他总是有点爱开玩笑。"}},{"en":"a person that you think is stupid because they annoy you","cn":"蠢货；废人","lab":"informal"},{"en":"an extra playing card that is used in some card games, usually as a wild card","cn":"（某些纸牌游戏中的）百搭，（大、小）王牌"}]}},"jinx":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"倒霉蛋；扫把星；不祥的人（或物）","en":"You can call something or someone that is considered to be unlucky or to bring bad luck a jinx .","ex":{"en":"He was beginning to think he was a jinx.","cn":"他开始认为自己是个倒霉蛋。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unlucky person often has bad things happen to them or things often go wrong by chance for them, not because of bad planning, stupidity, or carelessness","cn":""},{"en":"say with my luck when you think something bad is going to happen to you, and you are not surprised because you think you are an unlucky person","cn":""},{"en":"say just my luck when something bad has happened to you and you are not surprised because you think you are an unlucky person","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If your sister gets a flat tire every single time you ride in her car, she may have good reason to accuse you of being a jinx , or a bringer of bad luck."}]},"collocations":{"phrases":["VERB + JINX shake off The team seems to have shaken off the jinx that's been dogging them for months.","JINX + VERB hit sb, strike sb The injury jinx has struck Real Madrid. | dog sb, haunt sb","PREP. ~ on I'm sure there's a jinx on this car."]},"media":{"uk":"media/ldoce/hwd/bre/4/jinx0205.mp3","us":"media/ldoce/hwd/ame/5/jinx1.mp3"},"examples":[{"en":"I'm convinced there's a jinx on this car.","cn":"我深信这辆汽车沾上晦气了。"},{"en":"The company had suffered so many disasters that some employees feared a jinx.","cn":"公司遭受了这么多的灾难﹐有些员工担心遇上了霉运。"}],"oxford":{"phon":"dʒɪŋks","pos":"verb","senses":[{"en":"to bring bad luck in a mysterious way","cn":"厄运；霉运；不祥之人（或物）","ex":{"en":"I don't want to jinx anything by making promises.","cn":"我不想因为许下承诺而带来坏事。"}},{"en":"bad luck; somebody/something that is thought to bring bad luck in a mysterious way","cn":"厄运；霉运；不祥之人（或物）","ex":{"en":"I'm convinced there's a jinx on this car.","cn":"我深信这辆汽车沾上晦气了。"},"pos":"noun"}]}},"jungle":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"热带丛林；密林","en":"A jungle is a forest in a tropical country where large numbers of tall trees and plants grow very close together.","ex":{"en":"...the mountains and jungles of Papua New Guinea","cn":"巴布亚新几内亚的山脉和丛林"}},{"pos":"N-SING 单数名词","cn":"堆满东西的地方；杂乱无章的地方","en":"If you describe a place as a jungle, you are emphasizing that it is full of lots of things and very untidy.","ex":{"en":"...a jungle of stuffed birds, knick-knacks, potted plants.","cn":"堆满了鸟类标本、小摆设和盆栽植物的乱七八糟的地方"}},{"pos":"N-SING 单数名词","cn":"复杂困难的境况；尔虞我诈的环境","en":"If you describe a situation as a jungle, you dislike it because it is complicated and difficult to get what you want from it.","ex":{"en":"Social security law and procedure remain a jungle of complex rules.","cn":"有关社会保障的法律和程序仍旧是个充满错综复杂的规则的危险领域。"}},{"pos":"PHRASE 短语","cn":"丛林法则；弱肉强食的原则","en":"If you refer to the law of the jungle, you are referring to a situation in which there are no laws or rules to govern the way that people behave and people use force to get what they want.","ex":{"en":"If you make aggression pay, this becomes the law of the jungle","cn":"如果你通过侵略谋取利益，这就成了弱肉强食。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"丛林音乐（一种有着快节奏鼓点的舞曲）","en":"Jungle is a style of dance music with a fast drum beat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large area of land with a lot of trees growing closely together","cn":""},{"en":"an area of land covered with a lot of trees, that is smaller than a forest","cn":""},{"en":"an area of land that is covered with trees – used especially for describing the type of land in an area","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A jungle is a forest thick with trees, other plants, and animals. Jungles are a little dangerous, which is what people mean when they say, \"It's a jungle out there!\""}]},"collocations":{"phrases":["ADJ. dense, impenetrable, thick | tropical | concrete, urban (figurative) This outback area is a far cry from the city's concrete jungle.","JUNGLE + NOUN warfare","PREP. in ~ a temple deep in the Brazilian jungle | through ~ They hacked their way through dense jungle."]},"media":{"uk":"media/ldoce/hwd/bre/0/jungle0205.mp3","us":"media/ldoce/hwd/ame/2/jungle.mp3"},"examples":[{"en":"It's a jungle out there — you've got to be strong to succeed.","cn":"那是个弱肉强食的地方，要成功就得是强者。"},{"en":"Our garden is a complete jungle.","cn":"我们的花园杂草丛生。"}],"oxford":{"phon":"ˈdʒʌŋɡl","pos":"noun","senses":[{"en":"an area of tropical forest where trees and plants grow very thickly","cn":"（热带）丛林，密林","g":"[uncountable, countable]","ex":{"en":"The area was covered in dense jungle.","cn":"这个地区丛林密布。"}},{"en":"a dangerous or unfriendly place or situation, especially one where it is very difficult to be successful or to trust anyone","cn":"弱肉强食的世界；危险地带","g":"[singular]","ex":{"en":"It's a jungle out there—you've got to be strong to succeed.","cn":"那是个弱肉强食的地方，要成功就得是强者。"}},{"en":"a type of electronic dance music developed in the UK in the early 1990s, which has a fast drum beat and a strong slower bass beat","cn":"鼓与贝斯，鼓打贝斯（一种电子舞曲，20 世纪 90 年代初兴起于英国，以快速的鼓点节拍和强劲缓慢的贝斯节奏为特点）","g":"[uncountable]"}]}},"jockey":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赛马骑师","en":"A jockey is someone who rides a horse in a race."},{"pos":"VERB 动词","cn":"耍各种手腕获取；用尽手段谋取","en":"If you say that someone is jockeying for something, you mean that they are using whatever methods they can in order to get it or do it before their competitors can get it or do it.","ex":{"en":"The rival political parties are already jockeying for power","cn":"相互竞争的政党已经在耍各种手段争权夺势了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who rides horses in races","cn":"赛马骑师"},{"en":"to compete strongly to get into the best position or situation, or to get the most power 〔","cn":"为获得最佳位置﹑最有利形势或最大权力而〕激烈竞争"}]},"collocations":{"phrases":["ADJ. champion, top | winning | apprentice | amateur | jump (= who rides in races that involve jumping) | stable (= who rides the horses of a","JOCKEY + VERB ride (sth) Which jockey will be riding tomorrow? | win (sth) The race was won by top jockey Eddie Andrews."]},"media":{"uk":"media/ldoce/hwd/bre/8/jockey_n0205.mp3","us":"media/ldoce/hwd/ame/a/jockey1.mp3"},"examples":[{"en":"The bands are constantly jockeying with each other for the number one spot.","cn":"这些乐队经常相互耍手段以谋取榜首位置。"},{"en":"The runners jockeyed for position at the start.","cn":"赛跑选手一开始就力求抢占有利位置。"}],"oxford":{"phon":"ˈdʒɒki","pos":"noun","senses":[{"en":"a person who rides horses in races, especially as a job","cn":"（尤指职业的）赛马骑师","ex":{"en":"Which jockey will be riding tomorrow?","cn":"明天哪位骑师出赛？"}},{"en":"to try all possible ways of gaining an advantage over other people","cn":"耍各种手腕获取；运用手段谋取","ex":{"en":"The runners jockeyed for position at the start.","cn":"赛跑选手一开始就力求抢占有利位置。"},"pos":"verb"}]}},"jewel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宝石","en":"A jewel is a precious stone used to decorate valuable things that you wear, such as rings or necklaces.","ex":{"en":"...a golden box containing precious jewels.","cn":"盛放贵重宝石的金盒子"}},{"pos":"N-COUNT 可数名词","cn":"珍宝；珍贵的东西；出色的人；美貌超群的人","en":"If you describe something or someone as a jewel, you mean that they are better, more beautiful, or more special than other similar things or than other people.","ex":{"en":"Walk down Castle Street and admire our little jewel of a cathedral","cn":"沿城堡街走下去，欣赏一下我们美妙绝伦的大教堂。"}},{"pos":"PHRASE 短语","cn":"王冠上的宝石；最有成就（或最值得骄傲）之处","en":"If you refer to an achievement or thing as the jewel in someone's crown, you mean that it is considered to be their greatest achievement or the thing they can be most proud of.","ex":{"en":"His achievement is astonishing and this book is the jewel in his crown.","cn":"他的成就令人震惊，而这部书则是他的杰作。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a valuable stone, such as a diamond","cn":"宝石"},{"en":"a rare and valuable jewel such as a diamond or an emerald","cn":""},{"en":"a jewel that has been cut into a special shape","cn":""}]},"collocations":{"phrases":["ADJ. precious, priceless | bright, brilliant, sparkling","VERB + JEWEL wear","JEWEL + VERB sparkle","JEWEL + NOUN thief | box, case"]},"media":{"uk":"media/ldoce/hwd/bre/6/jewel0205.mp3","us":"media/ldoce/hwd/ame/4/jewel.mp3"},"examples":[{"en":"The family jewels are locked away in a safe.","cn":"家里的珠宝首饰都锁在保险柜里。"},{"en":"She loved dressing up and wearing priceless jewels.","cn":"她喜欢穿上盛装﹐戴上极为昂贵的珠宝首饰。"}],"oxford":{"phon":"ˈdʒuːəl","pos":"noun","senses":[{"en":"a precious stone such as a diamond, ruby, etc.","cn":"宝石"},{"en":"pieces of jewellery or beautiful objects that contain precious stones","cn":"珠宝首饰","g":"[usually plural]","ex":{"en":"The family jewels are locked away in a safe.","cn":"家里的珠宝首饰都锁在保险柜里。"}},{"en":"a small precious stone or piece of special glass that is used in the machine inside a watch","cn":"（手表的）宝石轴承"},{"en":"a person or thing that is very important or valuable","cn":"宝贝；难能可贵的人；珍贵的东西","lab":"informal","ex":{"en":"Alice, you are a jewel.","cn":"爱丽丝，你是一颗宝石。"}}]}},"jolt":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）震动；（使）摇动；（使）颠簸","en":"If something jolts or if something jolts it, it moves suddenly and quite violently.","ex":{"en":"The wagon jolted again","cn":"货车又开始颠簸起来。"}},{"pos":"VERB 动词","cn":"使震惊；使惊慌；使慌乱不安","en":"If something jolts someone, it gives them an unpleasant surprise or shock.","ex":{"en":"A stinging slap across the face jolted her","cn":"火辣辣的一巴掌打在脸上，她惊呆了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something shakes , it makes very small quick movements from side to side or up and down","cn":""},{"en":"to shake and repeatedly hit against something else, making a continuous noise","cn":""},{"en":"if something wobbles , it moves from side to side because it is not steady or not well balanced","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To jolt someone is to disturb them or make them jump. A jolt is sudden and jarring."}]},"collocations":{"phrases":["ADJ. nasty, severe, sharp, sickening, sudden, unpleasant | little, slight","VERB + JOLT feel | give My mother's death gave me a severe jolt. | send | receive She received such a jolt that she nearly dropped her cup.","PHRASES with a ~ The train started with a jolt. | ~ of The blow sent a jolt of pain through his body. | ~ to His dismissal was a severe jolt"]},"media":{"uk":"media/ldoce/hwd/bre/8/jolt_v0205.mp3","us":"media/ldoce/hwd/ame/8/jolt1.mp3"},"examples":[{"en":"The truck jolted and rattled over the rough ground.","cn":"卡车嘎吱嘎吱地在凹凸不平的地面上颠簸而行。"},{"en":"He was jolted forwards as the bus moved off.","cn":"公共汽车开动时他猛然向前晃了一下。"}],"oxford":{"phon":"dʒəʊlt","pos":"verb","senses":[{"en":"to move or to make somebody/something move suddenly and roughly","cn":"（使）震动，摇动，颠簸","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"The truck jolted and rattled over the rough ground.","cn":"卡车嘎吱嘎吱地在凹凸不平的地面上颠簸而行。"}},{"en":"to give somebody a sudden shock, especially so that they start to take action or deal with a situation","cn":"使受到震惊（而采取行动）；唤醒；使觉醒","g":"[transitive]","ex":{"en":"His remark jolted her into action.","cn":"他的话使她猛然醒悟而行动起来。"}},{"en":"a sudden rough movement","cn":"颠簸；震动；摇晃","ex":{"en":"The plane landed with a jolt.","cn":"飞机着陆时颠了一下。"},"pos":"noun"},{"en":"a sudden strong feeling, especially of shock or surprise","cn":"一阵强烈的感情（尤指震惊或惊讶）","ex":{"en":"a jolt of dismay","cn":"一阵惊诧"},"pos":"noun"}]}},"jutland":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a peninsula (= a long thin area of land with sea on three sides ) in northern Europe belonging partly to Denmark and partly to Germany. The Battle of Jutland was fought between the British navy and German navy off the coast of Jutland in World War I.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000006840.mp3","us":"media/ldoce/hwd/ame/7/p028-000006840.mp3"}},"jeopardize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使处于危险境地；危及；危害；损害","en":"To jeopardize a situation or activity means to do something that may destroy it or cause it to fail.","ex":{"en":"He has jeopardised the future of his government","cn":"他的行为已经危及到他这届政府的未来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that makes it more likely that someone or something will be harmed","cn":""},{"en":"to make it likely that something bad will happen to someone or something","cn":""},{"en":"to put someone or something in a dangerous or harmful situation","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Jeopardize means to put at risk or pose a threat. Jeopardize your career by posting silly pictures of yourself on Facebook. Jeopardize your friendships by posting silly pictures of your friends on Facebook."}]},"collocations":{"phrases":["ADV. seriously This scandal could seriously jeopardize his chances of being re-elected."]},"media":{"uk":"media/ldoce/hwd/bre/3/jeopardize0205.mp3","us":"media/ldoce/hwd/ame/5/jeopardize.mp3"},"examples":[{"en":"He would never do anything to jeopardize his career.","cn":"他决不会做任何有损于他事业的事。"},{"en":"large-scale military offensives which could jeopardize the UN peace process","cn":"可能会破坏联合国和平进程的大规模军事进攻"}],"oxford":{"phon":"ˈdʒepədaɪz","pos":"verb","senses":[{"en":"to risk harming or destroying something/somebody","cn":"冒…的危险；危及；危害；损害","ex":{"en":"He would never do anything to jeopardize his career.","cn":"他决不会做任何有损于他事业的事。"}}]}},"jane":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the main female character in the books and films about tarzan","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/p028-000006636.mp3","us":"media/ldoce/hwd/ame/1/p028-000006636.mp3"},"oxford":{"phon":"dʒeɪn","pos":"","senses":[{"en":"a first name for girls","cn":"简（女子名）"}]}},"jail":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"监狱；看守所","en":"A jail is a place where criminals are kept in order to punish them, or where people waiting to be tried are kept.","ex":{"en":"Three prisoners escaped from a jail.","cn":"3名囚犯越狱了。"}},{"pos":"VERB 动词","cn":"使入狱；监禁","en":"If someone is jailed, they are put into jail.","ex":{"en":"He was jailed for twenty years.","cn":"他被判了20年监禁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building where people are kept as a punishment for a crime or while they are waiting to go to court for their trial","cn":""},{"en":"a prison, or a similar smaller building where prisoners are kept for a short time","cn":""},{"en":"another way of spelling jail","cn":""}]},"collocations":{"phrases":["ADJ. county, local | high-security, maximum security, top security | private | overcrowded","VERB + JAIL go to He's gone to jail for fraud. | put sb in, send sb to, throw sb into | keep sb in | be freed from, be/get out of, be releas","JAIL + NOUN sentence, term","PREP. at a/the ~ riots at Strangeways jail | in (a/the) ~ How long has she been in jail? There was a fire in the jail last night."]},"media":{"uk":"media/ldoce/hwd/bre/3/jail_n0205.mp3","us":"media/ldoce/hwd/ame/e/jail1.mp3"},"examples":[{"en":"He has been released from jail.","cn":"他已从监狱里放出来了。"},{"en":"He was jailed for life for murder.","cn":"他因谋杀罪被终身监禁。"}],"oxford":{"phon":"dʒeɪl","pos":"noun","senses":[{"en":"a prison","cn":"监狱","lab":"especially North American English","ex":{"en":"She spent a year in jail.","cn":"她坐了一年牢。"}},{"en":"to put somebody in prison","cn":"监禁","ex":{"en":"He was jailed for life for murder.","cn":"他因谋杀罪被终身监禁。"},"pos":"verb"}]}},"jog":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（常作为锻炼）慢跑，慢步长跑","en":"If you jog, you run slowly, often as a form of exercise.","ex":{"en":"I got up early the next morning to jog","cn":"第二天早晨我一大早起来去慢跑。"}},{"pos":"VERB 动词","cn":"轻推；轻撞；轻碰","en":"If you jog something, you push or bump it slightly so that it moves.","ex":{"en":"Avoid jogging the camera.","cn":"请勿磕碰相机。"}},{"pos":"PHRASE 短语","cn":"唤起…的记忆；提醒","en":"If something or someone jogs your memory, they cause you to suddenly remember something that you had forgotten.","ex":{"en":"Police have planned a reconstruction of the crime tomorrow in the hope this will jog the memory of passers-by.","cn":"警方已计划明天再现犯罪现场，希望当时路过的人能想起些什么。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move very quickly, by moving your legs more quickly than when you walk","cn":""},{"en":"to run quite slowly for exercise over a long distance","cn":""},{"en":"to run somewhere as quickly as you can, especially because you have to do something urgently","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n 4 v","senses":[{"en":"When you jog , you run at a moderate pace, usually to get exercise. If you jog down the street, you'll pass people who are walking and be passed by people who are sprinting."}]},"collocations":{"phrases":["ADV. slowly, steadily","PREP. along, down, up They jogged steadily up the hill.","PHRASES go jogging She decided to go jogging each morning. | jog on the spot She was jogging on the spot to keep warm."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdejog.mp3","us":"media/ldoce/hwd/ame/6/jog1.mp3"},"examples":[{"en":"Someone jogged her elbow, making her spill her coffee.","cn":"有人不小心轻轻碰了一下她的胳膊肘儿，把咖啡弄洒了。"},{"en":"I like to go for a jog after work.","cn":"我喜欢在下班后慢跑锻炼。"}],"oxford":{"phon":"dʒɒɡ","pos":"verb","senses":[{"en":"to run slowly and steadily for a long time, especially for exercise","cn":"慢跑，慢步长跑（尤指锻炼）","g":"[intransitive]","ex":{"en":"I go jogging every evening.","cn":"我每天晚上都慢跑锻炼。"}},{"en":"to hit something lightly and by accident","cn":"（偶然地）轻击，轻撞，轻碰","g":"[transitive]","ex":{"en":"Someone jogged her elbow, making her spill her coffee.","cn":"有人不小心轻轻碰了一下她的胳膊肘儿，把咖啡弄洒了。"}},{"en":"a slow run, especially one done for physical exercise","cn":"慢跑（尤指锻炼）","ex":{"en":"I like to go for a jog after work.","cn":"我喜欢在下班后慢跑锻炼。"},"pos":"noun"},{"en":"a light push or knock","cn":"轻推；轻碰；轻击","pos":"noun"}]}},"jab":{"collins":{"senses":[{"pos":"VERB 动词","cn":"戳；刺；捅","en":"If you jab one thing into another, you push it there with a quick, sudden movement and with a lot of force.","ex":{"en":"He saw her jab her thumb on a red button — a panic button","cn":"他看到她用拇指按了一个红色按钮——紧急呼叫按钮。"}},{"pos":"N-COUNT 可数名词","cn":"戳；捅；猛击","en":"A jab is a sudden, sharp punch.","ex":{"en":"He was simply too powerful for his opponent, rocking him with a steady supply of left jabs.","cn":"对对手而言，他实在是太强大了，一顿结实的左刺拳打得对手摇摇晃晃。"}},{"pos":"N-COUNT 可数名词","cn":"注射；接种；预防针","en":"A jab is an injection of something into your blood to prevent illness.","ex":{"en":"...painful anti malaria jabs.","cn":"很疼的疟疾预防针"}},{"pos":"N-COUNT 可数名词","cn":"抨击；攻击","en":"You can refer to a sudden and unpleasant critical remark as a jab .","ex":{"en":"They have been sniping at each other, with the Democrats taking jabs at the president's handling of foreign policy.","cn":"他们一直在互相指责，其中民主党一方抨击总统的对外政策。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push something into or towards something else with short quick movements （","cn":"用…）戳﹐刺﹐捅"},{"en":"a medical method of curing someone who is ill or injured, for example by means of drugs or an operation","cn":""},{"en":"a series of treatments for a problem, especially a mental one, usually without drugs or operations","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you jab someone , you poke that person. No one on the school bus wants to sit next to the kid who tends to jab people in their ribs with his sharp elbows."}]},"collocations":{"phrases":["ADJ. left, right | hard, painful, sharp | elbow","VERB + JAB give sb | feel","PREP. ~ in/to Scott gave him a sharp left jab to the ribs. 2 injection","ADJ. flu, tetanus, typhoid, etc.","VERB + JAB have Did you have a flu jab this year? | give sb"]},"media":{"uk":"media/ldoce/hwd/bre/b/jab_n0205.mp3","us":"media/ldoce/hwd/ame/9/jab1.mp3"},"examples":[{"en":"She gave him a jab in the stomach with her elbow.","cn":"她用胳膊肘猛顶他的肚子。"},{"en":"She jabbed him in the ribs with her finger.","cn":"她用手指捅了捅他的腰。"}],"oxford":{"phon":"dʒæb","pos":"verb","senses":[{"en":"to push a pointed object into somebody/something, or in the direction of somebody/something, with a sudden strong movement","cn":"戳；刺；捅；猛击","g":"[transitive, intransitive]","ex":{"en":"She jabbed him in the ribs with her finger.","cn":"她用手指捅了捅他的腰。"}},{"en":"to vaccinate somebody against a disease","cn":"为某人接种疫苗","g":"[transitive, often passive]","lab":"British English, informal，，","ex":{"en":"He refuses to say whether he has been jabbed against Covid.","cn":"他拒绝透露自己是否受到过新冠病毒感染。"}},{"en":"a sudden strong hit with something pointed or with a fist (= a tightly closed hand)","cn":"戳；刺；捅；用拳猛击","ex":{"en":"She gave him a jab in the stomach with her elbow.","cn":"她用胳膊肘猛顶他的肚子。"},"pos":"noun"},{"en":"an injection to help prevent you from catching a disease","cn":"注射；接种；预防针","lab":"British English, informal，，","ex":{"en":"a flu jab","cn":"流感预防针"},"pos":"noun"}]}},"japan":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in East Asia consisting of four large islands, Hokkaido, Honshu, Shikoku, and Kyushu, and many smaller ones. Population: 127,253,075 (2014). Capital: Tokyo. The main religions are Shinto and Buddhism. Japan is an ancient civilization , but during the","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/p028-000006643.mp3","us":"media/ldoce/hwd/ame/e/japan1.mp3"},"oxford":{"phon":"dʒəˈpæn","pos":"noun","senses":[{"en":"a country consisting of a group of islands in East Asia","cn":"日本（东亚的群岛国家）"}]}},"jumper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"针织套衫","en":"A jumper is a warm knitted piece of clothing which covers the upper part of your body and your arms.","ex":{"en":"Isabel had on a simple jumper and skirt.","cn":"伊莎贝尔穿着素净的针织套衫和裙子。"}},{"pos":"N-COUNT 可数名词","cn":"（穿在衬衫或毛线衫外的）无袖连衣裙","en":"A jumper is a sleeveless dress that is worn over a blouse or sweater.","ex":{"en":"She wore a checkered jumper and had ribbons in her hair.","cn":"她穿着格子连衣裙，头上系着丝带。"}},{"pos":"N-COUNT 可数名词","cn":"善跳跃者；跳跃的人（或动物）","en":"If you refer to a person or a horse as a particular kind of jumper, you are describing how good they are at jumping or the way that they jump.","ex":{"en":"He is a terrific athlete and a brilliant jumper","cn":"他是个出色的运动员，弹跳力非常好。"}},{"pos":"N-COUNT 可数名词","cn":"跳跃运动员","en":"A particular kind of jumper is an athlete who takes part in a particular jumping event.","ex":{"en":"Packer began her career as a long jumper.","cn":"帕克开始运动生涯时是个跳远运动员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of clothing made of wool that covers the upper part of your body and arms","cn":"套头毛衣"},{"en":"a dress without sleeve s usually worn over a shirt 〔","cn":"通常穿在衬衣外面的〕无袖连衣裙"},{"en":"a person or animal that jumps","cn":"跳跃的人[动物]"}]},"collocations":{"phrases":["ADJ. baggy, loose, sloppy | tight | heavy, thick | light, thin | cashmere, cotton, woollen, woolly, etc. | knitted | crew-neck, polo-neck, t","VERB + JUMPER pull on | knit, make •"]},"media":{"uk":"media/ldoce/hwd/bre/b/jumper0205.mp3","us":"media/ldoce/hwd/ame/6/jumper.mp3"},"examples":[{"en":"He's a good jumper.","cn":"他的弹跳力特别好。"},{"en":"a woolly jumper","cn":"套头毛衣"}],"oxford":{"phon":"ˈdʒʌmpə(r)","pos":"noun","senses":[{"en":"a piece of clothing for the upper part of the body, made of wool or cotton, with long sleeves (= arms) and no buttons","cn":"套头衫；套头毛衣","lab":"British English","ex":{"en":"a woolly jumper","cn":"套头毛衣"}},{"en":"a loose dress without sleeves (= arms), usually worn over a blouse or sweater","cn":"背带裙，无袖连衣裙（通常穿在衬衣或套头衫外面）","lab":"North American English"},{"en":"a person, an animal or an insect that jumps","cn":"跳跃者；跳跃动物；跳虫","ex":{"en":"He's a good jumper.","cn":"他的弹跳力特别好。"}}]}},"joseph":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"in the Old Testament of the Bible, the favourite son of jacob . Joseph was given a ‘coat of many colours’ by his father, and this made his brothers jealous of him. They sold him as a slave to some Egyptians, but Joseph later became powerful by becoming an advi","cn":""},{"en":"in the New Testament of the Bible, the husband of mary , the mother of Jesus. Joseph was a carpenter in nazareth .","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/p028-000006795.mp3","us":"media/ldoce/hwd/ame/6/joseph1.mp3"},"oxford":{"phon":"ˈdʒəʊzəf","pos":"","senses":[{"en":"a first name for boys","cn":"约瑟夫（男子名）"}]}},"juror":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陪审团成员；陪审员","en":"A juror is a member of a jury."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of a jury","cn":"陪审员﹐陪审团成员"}]},"collocations":{"phrases":["VERB + JUROR swear in The jurors were sworn in."]},"media":{"uk":"media/ldoce/hwd/bre/f/juror0205.mp3","us":"media/ldoce/hwd/ame/9/juror.mp3"},"oxford":{"phon":"ˈdʒʊərə(r)","pos":"noun","senses":[{"en":"a member of a jury","cn":"陪审团成员；陪审员","ex":{"en":"The judge instructed jurors to disregard this information.","cn":"法官指示陪审员不要理会这一信息。"}}]}},"judo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"柔道；柔术","en":"Judo is a sport in which two people fight and try to throw each other to the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Japanese sport or method of defence, in which you try to throw your opponent onto the ground","cn":"柔道"}]},"collocations":{"phrases":["VERB + JUDO do, practise","JUDO + NOUN hold, move, throw She managed to get the man in a judo hold. | mat","PHRASES a black, etc. belt in judo He's a black belt in judo. He's got a brown belt in judo. •"]},"media":{"uk":"media/ldoce/hwd/bre/5/judo0205.mp3","us":"media/ldoce/hwd/ame/5/judo.mp3"},"examples":[{"en":"She's a black belt in judo.","cn":"她是柔道黑带高手。"},{"en":"He does judo.","cn":"他是练柔道的。"}],"oxford":{"phon":"ˈdʒuːdəʊ","pos":"noun","senses":[{"en":"a sport in which two people fight and try to throw each other to the ground","cn":"柔道","ex":{"en":"He does judo.","cn":"他是练柔道的。"}}]}},"jurisdiction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"司法权；审判权；管辖权","en":"Jurisdiction is the power that a court of law or an official has to carry out legal judgments or to enforce laws.","ex":{"en":"The British police have no jurisdiction over foreign bank accounts.","cn":"外国银行账户不在英国警方的管辖权限之内。"}},{"pos":"N-COUNT 可数名词","cn":"管辖区域；管辖范围","en":"A jurisdiction is a state or other area in which a particular court and system of laws has authority."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability or the right to control other people and make decisions that affect them","cn":""},{"en":"if someone has influence , they can use their important social position or their wealth to persuade other people to do things","cn":""},{"en":"the right to make decisions and control people, which a person has because of their job or official position","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Jurisdiction means having a legal right over something. A court can have jurisdiction over a legal question, a government can have jurisdiction over another country or territory. Even your parents could be said to have jurisdiction over you while you're under 18."}]},"collocations":{"phrases":["ADJ. limited | exclusive The commissioners had exclusive jurisdiction to decide. | civil, criminal, ecclesiastical","VERB + JURISDICTION have, retain The court has no jurisdiction in this case. | exercise The court may exercise its jurisdiction to compel th","PREP. beyond your ~ She acted beyond the jurisdiction of any teacher. | outside your ~ The matter is outside the jurisdiction of UK administ"]},"media":{"uk":"media/ldoce/hwd/bre/b/jurisdiction0205.mp3","us":"media/ldoce/hwd/ame/2/jurisdiction.mp3"},"examples":[{"en":"The committee has jurisdiction over all tax measures.","cn":"这个委员会有权制定所有税收措施。"}],"oxford":{"phon":"ˌdʒʊərɪsˈdɪkʃn","pos":"noun","senses":[{"en":"the authority that an official organization has to make legal decisions about somebody/something","cn":"司法权；审判权；管辖权","g":"[uncountable, countable]","ex":{"en":"The English court had no jurisdiction over the defendants.","cn":"英格兰法院对被告没有司法审判权。"}},{"en":"an area or a country in which a particular system of laws has authority","cn":"管辖区域；管辖范围","g":"[countable]","ex":{"en":"Practice varies between different European jurisdictions.","cn":"不同欧洲司法管辖区的做法有所不同。"}}]}},"jersey":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"泽西牛（一种浅棕色乳牛，所产牛奶含脂率很高）","en":"A Jersey cow or a Jersey is a light brown cow that produces very creamy milk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shirt made of soft material, worn by players of sports such as football and rugby 〔","cn":"足球﹑英式橄榄球等运动员穿的〕球衣，运动衫"},{"en":"a piece of clothing made of wool that covers the upper part of your body and your arms","cn":"毛衣﹐套头毛衣"},{"en":"a soft material made of cotton or wool","cn":"棉[毛]质柔软织物"}]},"collocations":{"phrases":["ADJ. thick | polo-neck, V-neck, etc. | cashmere | football, rugby","VERB + JERSEY pull on | knit •"]},"media":{"uk":"media/ldoce/hwd/bre/e/jersey0205.mp3","us":"media/ldoce/hwd/ame/9/jersey1.mp3"},"examples":[{"en":"made from 100% cotton jersey","cn":"用 100% 的棉织品做成"}],"oxford":{"phon":"ˈdʒɜːzi","pos":"noun","senses":[{"en":"a shirt worn by somebody playing a sports game","cn":"运动衫；球衣","g":"[countable]","ex":{"en":"Where can I find replica Iranian soccer jerseys?","cn":"在哪儿能找到仿制的伊朗足球衫？"}},{"en":"a knitted piece of clothing made of wool or cotton for the upper part of the body, with long sleeves and no buttons; a type of sweater","cn":"（毛或棉的）针织套头衫","g":"[countable]"},{"en":"a type of soft fine knitted cloth used for making clothes","cn":"平针织物","g":"[uncountable]","ex":{"en":"made from 100% cotton jersey","cn":"用 100% 的棉织品做成"}},{"en":"a type of light brown cow that produces high-quality milk","cn":"泽西牛（一种产优质奶的浅棕色乳牛）","g":"[countable]"},{"en":"the largest of the Channel Islands, off the north-west coast of France. The main town is St Helier. Jersey has its own government and tax system but has strong links with the UK, and is popular with British tourists. Both English and French are spoken on the island. It is known for its fruit and vegetables (particularly tomatoes and new potatoes called Jersey Royals). The item of clothing called a jersey takes its name from a type of knitted material originally made on the island.","cn":"球衣：法国西北海岸附近的海峡群岛中最大的。主要城镇是圣赫利尔。泽西岛拥有自己的政府和税收系统，但与英国有着紧密的联系，并受到英国游客的欢迎。岛上说英语和法语。它以其水果和蔬菜（尤其是西红柿和称为“皇家泽西岛”的新土豆）而闻名。一件名为“球衣”的服装的名称来源于该岛最初生产的一种针织材料。"},{"en":"(in the US) another name for the state of New Jersey","cn":"球衣：（在美国）新泽西州的别称"}]}},"jigsaw":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拼图；拼图玩具","en":"A jigsaw or jigsaw puzzle is a picture on cardboard or wood that has been cut up into odd shapes. You have to make the picture again by putting the pieces together correctly."},{"pos":"N-COUNT 可数名词","cn":"错综复杂的情况；谜团","en":"You can describe a complicated situation as a jigsaw .","ex":{"en":"...the jigsaw of high-level diplomacy.","cn":"高层外交的错综复杂"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture cut up into many pieces that you try to fit together","cn":"拼图玩具"},{"en":"a very complicated situation, especially one that you are trying to understand","cn":"复杂的情况﹔〔尤指〕谜团"},{"en":"a tool for cutting out shapes in thin pieces of wood","cn":"线锯﹐钢丝锯﹐镂花锯"}]},"collocations":{"phrases":["ADJ. giant, huge | 200-piece, etc.","QUANT. bit, piece One piece of the jigsaw is still missing.","VERB + JIGSAW do I used to enjoy doing jigsaws. | piece together (figurative) The police managed to piece together the jigsaw and reconstruc","JIGSAW + NOUN puzzle | piece","PHRASES a piece in a jigsaw (figurative) This is another piece in the jigsaw that will help us understand the biology of cancer."]},"media":{"img":["media/ldoce/img/jigsaw.jpg","media/thumb/jigsaw.jpg"],"uk":"media/ldoce/hwd/bre/1/brelasdejigsaw.mp3","us":"media/ldoce/hwd/ame/d/jigsaw.mp3"},"examples":[{"en":"to do a jigsaw","cn":"拼图画"},{"en":"As he explained, another piece of the jigsaw fell into place.","cn":"经他解释﹐这个谜团又有一部分被解开了。"}],"oxford":{"phon":"ˈdʒɪɡsɔː","pos":"noun","senses":[{"en":"a picture printed on cardboard (= very thick, stiff card) or wood, that has been cut up into a lot of small pieces of different shapes that you have to fit together again","cn":"拼图；拼板玩具","lab":"especially in North American English","ex":{"en":"to do a jigsaw","cn":"玩拼图"}},{"en":"a mysterious situation in which it is not easy to understand all the causes of what is happening; a complicated problem","cn":"神秘莫测的事物；谜团","ex":{"en":"If Hollis was a double agent then the Crabb affair fits neatly into the jigsaw.","cn":"如果霍利斯是双重间谍，那么克拉布事件就完美地解释了这个谜题中的疑点。"}},{"en":"a saw (= a type of tool) with a narrow blade for cutting designs in thin pieces of wood or metal","cn":"线锯；镂花锯；钢丝锯"}]}},"junior":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"职位（或地位）较低的；年资较浅的","en":"A junior official or employee holds a low-ranking position in an organization or profession.","ex":{"en":"Junior and middle-ranking civil servants have pledged to join the indefinite strike.","cn":"基层和中层公务员已承诺要加入到无限期罢工中来。"}},{"pos":"N-SING 单数名词","cn":"较年幼者；年少者","en":"If you are someone's junior, you are younger than they are.","ex":{"en":"She now lives with actor Denis Lawson, 10 years her junior.","cn":"她现在与比她小10岁的演员丹尼斯·劳森同居。"}},{"pos":"N-IN-NAMES 名称名词","cn":"小（用于男子名后以区别于家族中同名的长辈，缩略形式为Jr）","en":"Junior is sometimes used after the name of the younger of two men in a family who have the same name, sometimes in order to prevent confusion. The abbreviation Jr is also used.","ex":{"en":"His son, Arthur Ochs Junior, is expected to succeed him as publisher.","cn":"他的儿子，小阿瑟·奥克斯，有望子承父业继续从事出版。"}},{"pos":"N-COUNT 可数名词","cn":"（美国高中或大学的）三年级学生","en":"In the United States, a student in the third year of a high school or university course is called a junior.","ex":{"en":"Their youngest daughter Amy's a junior at the University of Evansville in Indiana","cn":"他们的小女儿埃米是印第安纳州埃文斯维尔大学三年级的学生。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not old","cn":""},{"en":"a small child is very young. Little sounds more informal than small , and is used especially in spoken English","cn":""},{"en":"between the ages of 13 and 19","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very a very junior officer | comparatively, fairly, quite, relatively She's quite junior in the organization.","PREP. to John is still junior to me at work."]},"media":{"uk":"media/ldoce/hwd/bre/e/junior_adj0205.mp3","us":"media/ldoce/hwd/ame/7/junior1.mp3"},"examples":[{"en":"She has coached many of our leading juniors.","cn":"她训练过我们许多名列前茅的青少年运动员。"},{"en":"I leave junior with Mom when I'm at work.","cn":"我工作时就把儿子留给母亲照看。"}],"oxford":{"phon":"ˈdʒuːniə(r)","pos":"adjective","senses":[{"en":"having a low rank in an organization or a profession","cn":"地位（或职位、级别）低下的","g":"[usually before noun]","sc":"of low rank","ex":{"en":"a junior partner/minister/officer","cn":"初级合伙人；政务次长；初级官员"}},{"en":"connected with young people below a particular age, rather than with adults, especially in sports","cn":"青少年的","g":"[only before noun]","sc":"in sport","ex":{"en":"He's a member of the club's junior team.","cn":"他是俱乐部青年队的成员。"}},{"en":"(especially in the US) used after the name of a man who has the same name as his father, to make it clear who is being referred to","cn":"小（父子同名时置于儿子的姓名后以示区分）","sc":"son"},{"en":"for children under the age of 11 or 13","cn":"为 11 或 13 岁以下儿童设立的","g":"[only before noun]","lab":"British English","sc":"school/college","ex":{"en":"a junior school","cn":"小学"}},{"en":"connected with the year before the last year in a high school or college","cn":"（四年制高中或大学中）三年级生的，三年级的","g":"[only before noun]","lab":"North American English","sc":"school/college","ex":{"en":"I spent my junior year in France.","cn":"我三年级是在法国念的。"}},{"en":"a young person below a particular age, rather than an adult","cn":"青少年；青少年运动员","g":"[countable]","sc":"in sport","ex":{"en":"She has coached many of our leading juniors.","cn":"她训练过我们许多名列前茅的青少年运动员。"},"pos":"noun"},{"en":"a child who goes to junior school","cn":"小学生","g":"[countable]","lab":"British English","sc":"in school/college","ex":{"en":"Sam is going to be a junior next year.","cn":"萨姆明年就要上学了。"},"pos":"noun"},{"en":"a student in the year before the last year at high school or college","cn":"（四年制高中或大学的）三年级学生","g":"[countable]","lab":"North American English","sc":"in school/college","pos":"noun"},{"en":"a person who has a job at a low level within an organization","cn":"职位较低者；低层次工作人员","g":"[countable]","lab":"especially British English","sc":"low level job","ex":{"en":"office juniors","cn":"办公室的低级职员"},"pos":"noun"},{"en":"a person’s young son","cn":"男孩子；年幼的儿子","g":"[singular]","lab":"North American English, informal，，","sc":"son","ex":{"en":"I leave junior with Mom when I'm at work.","cn":"我工作时就把儿子留给母亲照看。"},"pos":"noun"}]}},"jar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（用于存放食物的有盖的）玻璃罐，罐子， 坛子，广口瓶","en":"A jar is a glass container with a lid that is used for storing food.","ex":{"en":"...yellow cucumbers in great glass jars.","cn":"存放在大玻璃罐里的黄瓜"}},{"pos":"N-COUNT 可数名词","cn":"一罐，一坛（的量或物）","en":"You can use jar to refer to a jar and its contents, or to the contents only.","ex":{"en":"She opened up a glass jar of plums.","cn":"她打开了装满梅子的玻璃罐。"}},{"pos":"N-COUNT 可数名词","cn":"一杯酒","en":"If you have a jar, you have a drink with friends in a pub.","ex":{"en":"They had a few jars together.","cn":"他们一起喝了几杯。"}},{"pos":"VERB 动词","cn":"令人不快；使人不安；让人震惊","en":"If something jars on you, you find it unpleasant, disturbing, or shocking.","ex":{"en":"Sometimes a light remark jarred on her father.","cn":"有时候一句玩笑就会令她父亲不快。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）震动；（使）摇动","en":"If an object jars, or if something jars it, the object moves with a fairly hard shaking movement.","ex":{"en":"The ship jarred a little","cn":"船微微震动了一下。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a glass container with a wide top and a lid, used for storing food such as jam or honey , or the amount it contains 〔","cn":"玻璃〕罐子﹐广口瓶﹔一罐[一瓶]之量"},{"en":"a container made of clay, stone etc, used especially in the past for keeping food or drink in 〔","cn":"尤指过去盛食物或饮品的〕罐﹐坛﹐缸"},{"en":"a glass of beer","cn":"一杯啤酒"}]},"collocations":{"phrases":["ADJ. screw-top/screw-topped | airtight, sealed, stoppered | sterilized | preserving, storage | earthenware, glass, stone/stoneware | coffee,","VERB + JAR fill He was filling a jar with coins for his holiday. | seal | preserve sth in, store sth in","JAR + VERB be filled with sth, be full of sth, contain sth a jar full of pickled onions","PREP. in/into a/the ~ | ~ of a jar of marmalade"]},"media":{"uk":"media/ldoce/hwd/bre/3/jar_v0205.mp3","us":"media/ldoce/hwd/ame/9/jar1.mp3","img":["media/thumb/jar.jpg"]},"examples":[{"en":"The jolt seemed to jar every bone in her body.","cn":"这震动似乎把她浑身上下每根骨头都弄疼了。"},{"en":"The spade jarred on something metal.","cn":"铁锹撞在什么金属物件上发出刺耳的声音。"}],"oxford":{"phon":"dʒɑː(r)","pos":"noun","senses":[{"en":"a round glass container, with a lid (= cover), used for storing food, especially jam, honey, etc.","cn":"（玻璃）罐子，广口瓶","g":"[countable]","ex":{"en":"a storage jar","cn":"广口贮藏瓶"}},{"en":"a jar and what it contains","cn":"一罐，一瓶（的量）","g":"[countable]","ex":{"en":"a jar of coffee","cn":"一罐咖啡"}},{"en":"a tall container with a wide mouth, with or without handles, used in the past for carrying water, etc.","cn":"缸；坛子","g":"[countable]","ex":{"en":"a water jar","cn":"水缸"}},{"en":"a glass of beer","cn":"一杯啤酒","g":"[countable]","lab":"British English, informal，，","ex":{"en":"Do you fancy a jar after work?","cn":"下班后去喝一杯怎么样？"}},{"en":"an unpleasant shock, especially from things being suddenly shaken or hit","cn":"猛然震动；撞击","g":"[singular]","ex":{"en":"The fall gave him a nasty jar.","cn":"这一跤把他摔得够呛。"}},{"en":"to give or receive a sudden sharp painful knock","cn":"（使）撞击，受震动而疼痛","g":"[transitive, intransitive]","ex":{"en":"The jolt seemed to jar every bone in her body.","cn":"这震动似乎把她浑身上下每根骨头都弄疼了。"},"pos":"verb"},{"en":"to have an unpleasant or annoying effect","cn":"（对…）产生不快的影响；使烦躁","g":"[intransitive, transitive]","ex":{"en":"His constant moaning was beginning to jar on her nerves.","cn":"他不停的呻吟使她焦躁不安起来。"},"pos":"verb"},{"en":"to be different from something in a strange or unpleasant way","cn":"（与…）不协调，不和谐，相冲突","g":"[intransitive]","ex":{"en":"Her brown shoes jarred with the rest of the outfit.","cn":"她那双棕色的鞋与她的衣着不协调。"},"pos":"verb"}]}},"jackpot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（游戏或彩票的）头奖，最高奖；（尤指游戏中的）累积赌注金","en":"A jackpot is the most valuable prize in a game or lottery, especially when the game involves increasing the value of the prize until someone wins it.","ex":{"en":"A nurse won the £5 million jackpot.","cn":"一个护士赢得了500万英镑的头奖。"}},{"pos":"PHRASE 短语","cn":"取得巨大成功；赢了一大笔钱；交好运","en":"If you hit the jackpot, you have a great success, for example by winning a lot of money or having a piece of good luck."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is given to the person who wins a competition, game, or race","cn":""},{"en":"a special silver or gold container, shaped like a large cup with two handles, that is given to the winner of a sports competition","cn":""},{"en":"a round flat piece of metal that is given to someone who has won a race, game, or competition","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A jackpot is a pile of money won during a game such as a poker. It's also any example of good fortune."}]},"collocations":{"phrases":["VERB + JACKPOT get, hit, scoop, win (figurative) The National Theatre hit the jackpot with its first musical, &lsquo;Guys and Dolls&rsquo;.","JACKPOT + NOUN prize | winner","PREP. ~ in They scooped the jackpot in yesterday's lottery. | ~ of a prize jackpot of &pound; 100,000 | ~ on He won the jackpot on the footb"]},"media":{"uk":"media/ldoce/hwd/bre/3/jackpot0205.mp3","us":"media/ldoce/hwd/ame/d/jackpot.mp3"},"examples":[{"en":"( figurative ) United hit the jackpot (= were successful) with a 5-0 win over Liverpool.","cn":"联队以 5:0 狂胜利物浦队。"},{"en":"United hit the jackpot (= were successful) with a 5-0 win over Liverpool.","cn":""}],"oxford":{"phon":"ˈdʒækpɒt","pos":"noun","senses":[{"en":"a large amount of money that is the most valuable prize in a game of chance","cn":"（在碰运气游戏中的）头奖，最高奖","lab":"figurative","ex":{"en":"to win the jackpot","cn":"得头奖"}}]}},"jew":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"犹太人；犹太教徒","en":"A Jew is a person who believes in and practises the religion of Judaism."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose religion is Judaism, or who is a member of a group whose traditional religion is Judaism","cn":"犹太人﹔犹太教徒"}]},"vocab":{"pos":"n","senses":[{"en":"A Jew is someone who believes in the Jewish faith or has a cultural connection to Judaism. If your parents are Jewish, you're likely to describe yourself as a Jew ."}]},"collocations":{"phrases":["ADJ. devout, pious, practising, religious His family are all practising Jews. | secular | Hasidic, orthodox | Progressive, Reform | Ashkenaz","VERB + JEW be born He was born a Jew in first century Palestine. | become"]},"media":{"uk":"media/ldoce/hwd/bre/a/jew0205.mp3","us":"media/ldoce/hwd/ame/5/jew.mp3"},"oxford":{"phon":"dʒuː","pos":"noun","senses":[{"en":"a member of the people and cultural community whose traditional religion is Judaism and who come from the ancient Hebrew people of Israel; a person who believes in and practises Judaism","cn":"犹太人；犹太教徒","ex":{"en":"He was born a Jew in 1st-century Palestine.","cn":"他是犹太人，出生于 1 世纪的巴勒斯坦。"}}]}},"jelly":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"果冻","en":"Jelly is a transparent, usually coloured food that is eaten as a dessert. It is made from gelatine, fruit juice, and sugar.","ex":{"en":"...a large bowl of jelly.","cn":"一大碗果冻"}},{"pos":"N-MASS 物质名词","cn":"（通常涂在面包上浓稠的）果酱","en":"Jelly is a thick sweet food that is made by cooking fruit with a large amount of sugar, and that is usually spread on bread.","ex":{"en":"I had two peanut butter and jelly sandwiches.","cn":"我吃了两个放了花生酱和果酱的三明治。"}},{"pos":"N-MASS 物质名词","cn":"（稀薄而透明的）果酱","en":"Jelly is a thin clear sweet food that is made by cooking fruit with a large amount of sugar.","ex":{"en":"...toast piled thick with butter and bramble jelly.","cn":"涂抹了厚厚的黄油和黑莓酱的烤面包片"}},{"pos":"N-VAR 可变名词","cn":"胶状物；胶凝物","en":"A jelly is a transparent substance that is not completely solid.","ex":{"en":"...meat in jelly.","cn":"猪肉冻"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft sweet food made from fruit juice and gelatin","cn":"果冻"},{"en":"a thick sweet substance made from boiled fruit and sugar with no pieces of fruit in it, eaten especially on bread 〔","cn":"常用于涂抹面包的〕果酱"},{"en":"a soft solid substance made from meat juices and gelatin","cn":"肉冻"}]},"collocations":{"phrases":["VERB + JELLY eat, have | make Shall I make a jelly for pudding?","JELLY + VERB set Put the jelly in the fridge to set. | wobble","PREP. in ~ fruit in jelly •"]},"media":{"uk":"media/ldoce/hwd/bre/a/jelly0205.mp3","us":"media/ldoce/hwd/ame/f/jelly.mp3"},"examples":[{"en":"jelly and ice cream","cn":"果冻冰淇淋"},{"en":"blackcurrant jelly","cn":"黑加仑果酱"}],"oxford":{"phon":"ˈdʒeli","pos":"noun","senses":[{"en":"a cold sweet transparent food, made from gelatin, sugar and fruit juice, that shakes when it is moved","cn":"果冻","g":"[uncountable, countable]","lab":"British English","ex":{"en":"jelly and ice cream","cn":"果冻冰激凌"}},{"en":"a substance like jelly made from gelatin and meat juices, served around meat, fish, etc.","cn":"肉冻","g":"[uncountable]","ex":{"en":"chicken in jelly","cn":"鸡肉冻"}},{"en":"a type of jam that does not contain any pieces of fruit","cn":"（不含水果块的）果酱","g":"[uncountable, countable]","ex":{"en":"blackcurrant jelly","cn":"黑加仑果酱"}},{"en":"any thick sticky substance, especially a type of cream used on the skin","cn":"胶状物，胶凝物（尤指护肤霜）","g":"[uncountable]"},{"en":"a light plastic shoe designed for wearing on the beach and in the sea","cn":"（海滩和海上穿的）轻便塑料鞋","g":"[countable]"}]}},"jaw":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"下巴；下颌","en":"Your jaw is the lower part of your face below your mouth. The movement of your jaw is sometimes considered to express a particular emotion. For example, if your jaw drops, you are very surprised.","ex":{"en":"He thought for a moment, stroking his well-defined jaw","cn":"他摸着自己轮廓分明的下巴想了一会儿。"}},{"pos":"N-COUNT 可数名词","cn":"颌","en":"A person's or animal's jaws are the two bones in their head which their teeth are attached to.","ex":{"en":"...a forest rodent with powerful jaws.","cn":"颌骨发达的森林啮齿类动物"}},{"pos":"N-PLURAL 复数名词","cn":"危险的局面；令人不快的情形","en":"If you talk about the jaws of something unpleasant such as death or hell, you are referring to a dangerous or unpleasant situation.","ex":{"en":"A family dog rescued a newborn boy from the jaws of death.","cn":"一只家养犬把一个新生男婴从鬼门关救了回来。"}},{"pos":"","cn":"","en":"to snatch defeat from the jaws of victory→see: ; to snatch victory from the jaws of defeat→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two bones that your teeth are in","cn":"颌(骨)"},{"en":"the lower part of your face. Its shape is sometimes thought to show your character","cn":"下巴﹐下颌〔下巴的形状有时被认为能够显示一个人的性格〕"},{"en":"used to say that someone looked surprised or shocked","cn":"某人张口结舌〔形容惊讶或震惊〕"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Your jaw is the bottom, hinged part of your skull that holds your teeth. When you have a cavity, it can make your whole jaw hurt."}]},"collocations":{"phrases":["ADJ. bottom, lower | top, upper | firm, strong | clenched, set | slack | jutting, lantern (= in which the lower part sticks out), thrusting ","VERB + JAW clench, set | finger, rub, stroke He fingered his jaw thoughtfully. | break, dislocate, fracture","JAW + VERB drop, sag My jaw dropped in astonishment when I saw the size of the audience. | be set, clench, set, tighten Her jaw was set, rea","JAW + NOUN bone, muscle | injury","PREP. in your ~ A muscle in his jaw pulsed angrily. | on your ~ He had two days' growth of stubble on his jaw. | to the ~ a punch to the jaw","PHRASES the line/set of your jaw The stern set of the officer's jaw made Tony realize he was in trouble. 2 jaws: mouth","ADJ. gaping, open | massive, powerful A shark can crush a boat with its massive jaws. | slavering The slavering jaws of the guard dog stoppe","VERB + JAW clamp, close, lock, sink The dog locked its jaws on her leg and wouldn't let go. A spider sank its jaws into my ankle. | escape ("]},"media":{"uk":"media/ldoce/hwd/bre/4/jaw_n0205.mp3","us":"media/ldoce/hwd/ame/8/jaw1.mp3"},"examples":[{"en":"The alligator's jaws snapped shut.","cn":"钝吻鳄的嘴吧嗒一声闭上了。"},{"en":"He has a strong square jaw.","cn":"他长着一副结实的方下巴。"}],"oxford":{"phon":"dʒɔː","pos":"noun","senses":[{"en":"either of the two bones at the bottom of the face that contain the teeth and move when you talk or eat","cn":"颌","g":"[countable]","ex":{"en":"the top/upper jaw","cn":"上颌"}},{"en":"the lower part of the face; the lower jaw","cn":"下巴；下颌","g":"[singular]","ex":{"en":"He has a strong square jaw.","cn":"他长着结实的方下巴。"}},{"en":"the mouth and teeth of a person or an animal","cn":"口部；嘴","g":"[plural]","ex":{"en":"The alligator's jaws snapped shut.","cn":"钝吻鳄的嘴吧嗒一声闭上了。"}},{"en":"the parts of a tool or machine that are used to hold things tightly","cn":"（工具或机器的）钳夹部分，钳口","g":"[plural]","ex":{"en":"the jaws of a vice","cn":"虎钳口"}},{"en":"to talk, especially to talk a lot or for a long time","cn":"唠唠叨叨；喋喋不休","pos":"verb"}]}},"junk":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"废弃物；废旧物","en":"Junk is old and used goods that have little value and that you do not want any more.","ex":{"en":"Rose finds her furniture in junk shops","cn":"罗丝从旧货店买来了家具。"}},{"pos":"VERB 动词","cn":"丢弃；抛弃；废弃","en":"If you junk something, you get rid of it or stop using it.","ex":{"en":"Consumers will not have to junk their old cassettes to use the new format","cn":"消费者将不必丢弃他们的旧盒带而采用新的制式。"}},{"pos":"N-COUNT 可数名词","cn":"中国式（平底）帆船；舢板","en":"A junk is a Chinese sailing boat that has a flat bottom and square sails."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this when you are talking about two or more things of different types and you do not need to say what they are","cn":""},{"en":"objects or possessions of different types","cn":""},{"en":"things that are not useful and should be thrown away, for example because they are old or broken","cn":""}]},"collocations":{"phrases":["ADJ. old sculptures made from old junk and scrap metal","QUANT. bit, piece There were bits of junk lying around.","JUNK + VERB lie about/around","JUNK + NOUN shop | room They cleared out the junk room to make a tiny bedroom. | heap | material He made the boat out of junk materials."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdejunk.mp3","us":"media/ldoce/hwd/ame/e/junk1.mp3"},"examples":[{"en":"I've cleared out all that old junk in the attic.","cn":"我把阁楼里所有的废旧杂物都清除干净了。"},{"en":"There's nothing but junk on the TV.","cn":"电视上全是些无聊的东西。"}],"oxford":{"phon":"dʒʌŋk","pos":"noun","senses":[{"en":"things that are considered to have no use or value","cn":"无用的东西；无价值的东西","g":"[uncountable]","lab":"informal, disapproving，，","ex":{"en":"I've cleared out all that old junk in the attic.","cn":"我把阁楼里所有的废旧杂物都清除干净了。"}},{"en":"food that is quick and easy to prepare and eat but that is thought to be bad for your health","cn":"垃圾食品（制作、食用方便却有害健康）","g":"[uncountable]","lab":"informal, disapproving，，"},{"en":"a Chinese boat with a square sail and a flat bottom","cn":"中国式帆船；戎克船","g":"[countable]"},{"en":"to get rid of something because it is no longer valuable or useful","cn":"把…当作废物扔弃；丢弃；废弃","ex":{"en":"All their old computers had been junked.","cn":"他们所有的旧电脑都被报废了。"},"pos":"verb"}]}},"junta":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（武力夺取政权的）军事集团，军政府","en":"A junta is a military government that has taken power by force, and not through elections."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a government in which one person or group has total power and uses it unfairly and cruelly","cn":""},{"en":"a country where the police and other people who work for the government have too much power and control people's lives too much","cn":""},{"en":"a government run by a small group of army officers who have not been elected but have taken power by force","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When a government is overthrown, the coalition or group that forms and takes control is called a junta. If the military has seized control, as so often happens, then the group is called a military junta ."}]},"collocations":{"phrases":["ADJ. ruling | civilian, military, revolutionary","VERB + JUNTA form | dissolve, overthrow","JUNTA + VERB appoint sb The civilian junta appointed a prime minister.","JUNTA + NOUN leader, member"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld44junta.mp3","us":"media/ldoce/hwd/ame/3/junta.mp3"},"oxford":{"phon":"ˈdʒʌntə","pos":"noun","senses":[{"en":"a military government that has taken power by force","cn":"（武力夺取政权的）军人集团，军政府","ex":{"en":"The civilian junta appointed a prime minister.","cn":"文官政府任命了首相。"}}]}},"jargon":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"行话；行业术语；黑话","en":"You use jargon to refer to words and expressions that are used in special or technical ways by particular groups of people, often making the language difficult to understand.","ex":{"en":"The manual is full of the jargon and slang of self-improvement courses.","cn":"手册里满是有关自修课程的行话术语。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a single group of letters that are used together with a particular meaning","cn":""},{"en":"a word that you use for a particular thing, place, organization etc","cn":""},{"en":"a word or group of words that is used in a specific subject or area of language","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Jargon usually means the specialized language used by people in the same work or profession. Internet advertising jargon includes the new words \"click throughs\" and \"page views.\""}]},"collocations":{"phrases":["ADJ. current | incomprehensible, obscure | unnecessary | academic, computer, legal, scientific, technical","QUANT. piece","VERB + JARGON speak (in), use He always speaks in obscure legal jargon. | avoid","PREP. in ~ in computer jargon | ~ for &lsquo;All necessary means&rsquo; is diplomatic jargon for &lsquo;war&rsquo;."]},"media":{"uk":"media/ldoce/hwd/bre/c/jargon0205.mp3","us":"media/ldoce/hwd/ame/d/jargon.mp3"},"examples":[{"en":"Try to avoid using too much technical jargon.","cn":"尽量避免使用太多的技术用语。"},{"en":"medical/legal/computer, etc. jargon","cn":"医学、法律、计算机等术语"}],"oxford":{"phon":"ˈdʒɑːɡən","pos":"noun","senses":[{"en":"words or expressions that are used by a particular profession or group of people, and are difficult for others to understand","cn":"行话；行业术语；切口","ex":{"en":"medical/legal/computer, etc. jargon","cn":"医学、法律、计算机等术语"}}]}},"jut":{"collins":{"senses":[{"pos":"VERB 动词","cn":"凸出；伸出","en":"If something juts out, it sticks out above or beyond a surface.","ex":{"en":"The northern end of the island juts out like a long, thin finger into the sea","cn":"岛屿的北端像一根细长的手指一样伸入海中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（使身体部位）凸出；（尤指）翘起（下巴）","en":"If you jut a part of your body, especially your chin, or if it juts, you push it forward in an aggressive or determined way.","ex":{"en":"His jaw jutted stubbornly forward; he would not be denied","cn":"他的下巴倔强地翘着；他不会甘心被拒绝。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stick out from a surface or through an opening","cn":""},{"en":"to stick out and point upwards","cn":""},{"en":"to stick out, especially to stick out further than is usual or expected","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When something juts , it extends outward. Your nose juts out from your face, just as your ears jut from your head. If you’re feeling determined, you might jut out your chin."}]},"media":{"uk":"media/ldoce/hwd/bre/e/jut0205.mp3","us":"media/ldoce/hwd/ame/7/jut.mp3"},"examples":[{"en":"A row of small windows jutted out from the roof.","cn":"有一排小窗户从房顶上突出来。"},{"en":"She jutted her chin out stubbornly.","cn":"她倔强地把下巴翘得高高的。"}],"oxford":{"phon":"dʒʌt","pos":"verb","senses":[{"en":"to stick out further than the surrounding surface, objects, etc.; to make something stick out","cn":"（使）突出，伸出","ex":{"en":"A row of small windows jutted out from the roof.","cn":"有一排小窗户从房顶上突出来。"}}]}}});
